window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[340]={"id":"340","numero":340,"titre":"Accidents vasculaires cérébraux","objectifs":[{"id":"340-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la classification des accidents vasculaires cérébraux (AVC)","contenu":"<p>Un <span class=\"kw-def\">accident vasculaire cérébral</span> est un <span class=\"kw-clinique\">déficit neurologique focal</span> d'installation <span class=\"kw-clinique\">brutale</span> dû à une <span class=\"kw-clinique\">lésion</span> du parenchyme cérébral d'<span class=\"kw-def\">origine vasculaire</span>. La <span class=\"kw-def\">définition OMS</span> retient un développement rapide de signes de dysfonction cérébrale durant <span class=\"kw-chiffre\">&gt; 24 h</span> (ou conduisant au décès), <span class=\"kw-alerte\">sans autre cause apparente qu'une origine vasculaire</span>.</p>\n    <p>Trois caractères sémiologiques fondent le diagnostic :</p>\n    <ul>\n      <li><strong>Focal</strong> — la perte de fonction correspond à la <span class=\"kw-clinique\">lésion</span> d'une structure anatomique donnée (motricité, sensibilité, vision, langage).</li>\n      <li><strong>Brutal</strong> — <span class=\"kw-clinique\">déficit maximal d'emblée</span>, sans prodrome, d'intensité maximale en <span class=\"kw-chiffre\">&lt; 2 minutes</span>.</li>\n      <li><strong>Déficitaire</strong> — <span class=\"kw-alerte\">seules les pertes de fonction comptent</span> ; toute manifestation productive (clonies, phosphènes, mouvements anormaux) fait <span class=\"kw-alerte\">remettre en cause le diagnostic</span>.</li>\n    </ul>\n    <table >\n      <thead><tr><th>Type</th><th>Part</th><th>Sous-types &amp; mécanisme</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">AVC ischémique</span></td><td><span class=\"kw-chiffre\">80 %</span></td><td><strong><span class=\"kw-clinique\">Infarctus</span> cérébral constitué :</strong> <span class=\"kw-clinique\">nécrose</span> du parenchyme par occlusion artérielle ;<br><strong>Accident <span class=\"kw-etio\">ischémique</span> transitoire (<span class=\"kw-alerte\">AIT</span>) :</strong> <span class=\"kw-clinique\">ischémie focale brève</span>, <span class=\"kw-radio\">sans lésion en imagerie</span></td></tr>\n        <tr><td><span class=\"kw-def\">AVC hémorragique</span></td><td><span class=\"kw-chiffre\">20 %</span></td><td><strong>Hémorragie intraparenchymateuse (HIP) :</strong> <span class=\"kw-chiffre\">15 %</span>, saignement dans le parenchyme ;<br><strong>Hémorragie sous-arachnoïdienne (HSA) :</strong> <span class=\"kw-chiffre\">5 %</span>, saignement méningé — traitée à l'item 341</td></tr>\n        <tr><td><span class=\"kw-def\">Thrombose veineuse cérébrale</span></td><td><span class=\"kw-chiffre\">&lt; 2 %</span></td><td>Occlusion d'un sinus ou d'une veine cérébrale — <span class=\"kw-alerte\">n'obéit pas à un territoire artériel</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Le terme « <span class=\"kw-alerte\">AVC</span> » regroupe l'ensemble des pathologies vasculaires cérébrales <span class=\"kw-def\">artérielles</span> et <span class=\"kw-def\">veineuses</span>. Sont <span class=\"kw-ci\">exclus</span> du cadre : les syncopes et malaises sans déficit focal, et les ischémies globales par bas débit. Environ <span class=\"kw-chiffre\">1/4</span> des <span class=\"kw-alerte\">AVC</span> sont des <span class=\"kw-def\">récidives</span>.</div>","frequence":0},{"id":"340-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque des AVC","contenu":"<p>L'<span class=\"kw-alerte\">AVC</span> touche les sujets de <span class=\"kw-chiffre\">≥ 65 ans</span> dans <span class=\"kw-chiffre\">75 %</span> des cas (âge moyen <span class=\"kw-chiffre\">73 ans</span>), mais il survient à tout âge. Le <span class=\"kw-clinique\">contrôle des 9 principaux facteurs de risque</span> (<span class=\"kw-etio\">HTA</span>, diabète, dyslipidémie, obésité, tabac, alcool, <span class=\"kw-clinique\">fibrillation</span> atriale, <span class=\"kw-etio\">sédentarité</span>, alimentation déséquilibrée) <span class=\"kw-alerte\">réduit de 90 % le risque d'AVC</span>.</p>\n    <table >\n      <thead><tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n      <tbody>\n        <tr>\n          <td><span class=\"kw-def\">Modifiables — FRCV</span></td>\n          <td>\n            <strong><span class=\"kw-etio\">HTA</span> :</strong> <span class=\"kw-alerte\">principal facteur de risque</span> (<span class=\"kw-chiffre\">RR = 4</span>), <span class=\"kw-etio\">ischémique</span> comme hémorragique — <span class=\"kw-chiffre\">&gt; 50 %</span> des <span class=\"kw-alerte\">AVC</span> surviennent sur <span class=\"kw-etio\">HTA</span> chronique ;<br>\n            <strong><span class=\"kw-etio\">Tabac</span> :</strong> <span class=\"kw-chiffre\">RR = 2</span>, facteur majeur d'<span class=\"kw-etio\">athérosclérose</span> carotidienne ;<br>\n            <strong><span class=\"kw-etio\">Diabète</span> :</strong> <span class=\"kw-chiffre\">RR = 1,5</span> ;<br>\n            <strong><span class=\"kw-etio\">Hypercholestérolémie</span> :</strong> <span class=\"kw-chiffre\">RR = 1,5</span>, facteur plus accessoire pour l'<span class=\"kw-clinique\">infarctus</span> cérébral\n          </td>\n        </tr>\n        <tr>\n          <td><span class=\"kw-def\">Modifiables — autres</span></td>\n          <td>\n            <strong><span class=\"kw-etio\">Alcoolisme chronique</span> :</strong> risque croissant au-delà de <span class=\"kw-chiffre\">&gt; 3 verres/jour</span> (<span class=\"kw-clinique\">infarctus</span> et HIP) ;<br>\n            <strong><span class=\"kw-etio\">Fibrillation atriale</span> :</strong> cardiopathie emboligène majeure ;<br>\n            <strong><span class=\"kw-etio\">Migraine avec aura</span> :</strong> femme jeune, surtout si <span class=\"kw-etio\">tabac</span> + <span class=\"kw-etio\">contraception orale</span> associés ;<br>\n            <strong><span class=\"kw-etio\">Contraception œstroprogestative</span> :</strong> faible sur-risque, lié à l'<span class=\"kw-alerte\">effet synergique avec le tabac</span> ;<br>\n            <strong>Discutés :</strong> <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">syndrome métabolique</span>, <span class=\"kw-etio\">sédentarité</span>, <span class=\"kw-etio\">SAHOS</span>\n          </td>\n        </tr>\n        <tr>\n          <td><span class=\"kw-def\">Non modifiables</span></td>\n          <td><span class=\"kw-etio\">Âge</span> ; <span class=\"kw-etio\">sexe masculin</span> ; <span class=\"kw-etio\">antécédents familiaux et personnels</span> d'événement cérébro-vasculaire</td>\n        </tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Hors <span class=\"kw-alerte\">AIT</span> ou <span class=\"kw-clinique\">infarctus</span> avéré, il n'y a <span class=\"kw-ci\">aucun intérêt à l'aspirine au long cours</span> en <span class=\"kw-def\">prévention primaire</span> neurovasculaire. La <span class=\"kw-ttt\">chirurgie</span> d'une sténose carotide asymptomatique n'est discutée que si elle est <span class=\"kw-chiffre\">&gt; 60 %</span> avec une espérance de vie <span class=\"kw-chiffre\">&gt; 5 ans</span>.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 224 — <span class=\"kw-etio\">HTA</span> · 247 — Diabète · 223 — Dyslipidémie · 75 — Addiction Tabac · 76 — Addiction à l'alcool</em></p>","frequence":1},{"id":"340-3","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l'urgence diagnostique et thérapeutique des AVC","contenu":"<p>L'<span class=\"kw-alerte\">AVC</span> est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique absolue</span> : le <span class=\"kw-alerte\">pronostic vital</span> immédiat et le <span class=\"kw-def\">pronostic</span> fonctionnel ultérieur dépendent de la rapidité de la prise en charge. Chaque minute d'ischémie détruit <span class=\"kw-chiffre\">2 millions de neurones</span> — « <span class=\"kw-def\">time is brain</span> ».</p>\n    <ul>\n      <li><strong>Reconnaître :</strong> les critères <span class=\"kw-def\">FAST</span> (<em>Face</em> — <span class=\"kw-clinique\">asymétrie faciale</span> ; <em>Arm</em> — <span class=\"kw-clinique\">déficit d'un membre</span> ; <em>Speech</em> — <span class=\"kw-clinique\">trouble du langage</span> ; <em>Time</em> — noter l'heure et appeler) sont diffusés au grand public.</li>\n      <li><strong>Alerter :</strong> <span class=\"kw-clinique\">contact du 15 sans délai</span> pour tout symptôme évocateur.</li>\n      <li><strong>Orienter :</strong> admission en <span class=\"kw-def\">unité neurovasculaire</span> (UNV) — quels que soient l'âge, le sexe et la gravité.</li>\n      <li><strong>Noter l'heure de début</strong> des symptômes : elle conditionne l'<span class=\"kw-alerte\">éligibilité aux traitements de revascularisation</span>.</li>\n    </ul>\n    <p>Les <span class=\"kw-def\">fenêtres thérapeutiques</span> sont étroites : <span class=\"kw-ttt\">thrombolyse intraveineuse</span> jusqu'à <span class=\"kw-chiffre\">4 h 30</span>, <span class=\"kw-ttt\">thrombectomie mécanique</span> jusqu'à <span class=\"kw-chiffre\">6 h</span> (extensible à <span class=\"kw-chiffre\">24 h</span> sur imagerie de sélection). La prise en charge en <span class=\"kw-def\">UNV</span> réduit la morbi-<span class=\"kw-def\">mortalité</span> : <span class=\"kw-chiffre\">1 décès ou 1 handicap évité pour 20 patients</span> traités.</p>\n    <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute suspicion d'<span class=\"kw-alerte\">AVC</span> impose une <span class=\"kw-imagerie\">imagerie cérébrale en urgence</span> : <span class=\"kw-alerte\">seule l'imagerie distingue l'AVC ischémique de l'AVC hémorragique</span>, distinction indispensable avant tout traitement.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 92 — Déficit moteur-sensitif membres</em></p>","frequence":1},{"id":"340-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l'ischémie cérébrale","contenu":"<p>Le fonctionnement cérébral exige un apport sanguin constant en oxygène et en glucose ; en l'<span class=\"kw-alerte\">absence de réserve</span> en ces deux substrats, toute <span class=\"kw-ttt\">réduction</span> aiguë du débit artériel cérébral entraîne une souffrance du parenchyme situé en aval de l'occlusion.</p>\n    <p>L'<span class=\"kw-def\">ischémie cérébrale</span> relève de deux mécanismes :</p>\n    <table >\n      <thead><tr><th>Mécanisme</th><th>Description</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Thrombotique / thromboembolique</span></td><td><span class=\"kw-alerte\">Le plus fréquent</span> — occlusion artérielle par un <span class=\"kw-etio\">thrombus</span> formé sur place ou migré (embole)</td></tr>\n        <tr><td><span class=\"kw-def\">Hémodynamique</span></td><td>Rare — chute de la perfusion sans occlusion (effondrement tensionnel) : régionale sur sténose pré-occlusive, ou systémique (<span class=\"kw-etio\">arrêt cardiaque</span>) ; touche volontiers une zone jonctionnelle entre deux territoires</td></tr>\n      </tbody>\n    </table>\n    <p>En aval de l'occlusion coexistent deux zones, dont la distinction commande toute la stratégie thérapeutique :</p>\n    <table >\n      <thead><tr><th>Zone</th><th>Devenir</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Zone centrale de nécrose</span></td><td><span class=\"kw-alerte\">Nécrose immédiate et irréversible</span> — responsable des <span class=\"kw-clinique\">séquelles neurologiques définitives</span></td></tr>\n        <tr><td><span class=\"kw-def\">Zone de pénombre ischémique</span></td><td>Souffrance tissulaire <span class=\"kw-clinique\">réversible</span> si le débit est rétabli dans les <span class=\"kw-chiffre\">premières heures</span> — responsable des symptômes du patient, c'est la <span class=\"kw-alerte\">cible des traitements d'urgence de reperfusion</span></td></tr>\n      </tbody>\n    </table>\n    <figure class=\"avc-schema\">\n      <svg viewBox=\"0 0 560 290\" role=\"img\" aria-label=\"Schéma de l'ischémie cérébrale : une artère occluse par un thrombus prive son territoire d'aval. Au centre, la zone de nécrose irréversible ; tout autour, la pénombre ischémique encore sauvable si le débit est rétabli précocement, partiellement alimentée par les suppléances du polygone de Willis.\">\n        <!-- pénombre : zone sauvable -->\n        <ellipse cx=\"375\" cy=\"145\" rx=\"150\" ry=\"108\" fill=\"var(--spe-infectio)\" fill-opacity=\"0.16\" stroke=\"var(--spe-infectio)\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/>\n        <!-- noyau de nécrose -->\n        <ellipse cx=\"375\" cy=\"145\" rx=\"80\" ry=\"58\" fill=\"var(--spe-mir)\"/>\n        <!-- artère afférente + lumière + thrombus occlusif -->\n        <path d=\"M8 145 H240\" stroke=\"var(--ink-muted)\" stroke-width=\"15\" fill=\"none\" stroke-linecap=\"round\"/>\n        <path d=\"M8 145 H236\" stroke=\"var(--bg-card)\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>\n        <circle cx=\"222\" cy=\"145\" r=\"15\" fill=\"var(--spe-mir)\"/>\n        <line x1=\"222\" y1=\"120\" x2=\"222\" y2=\"100\" stroke=\"var(--spe-infectio)\" stroke-width=\"1.5\"/>\n        <!-- collatérales (polygone de Willis) suppléant la pénombre -->\n        <path d=\"M548 38 Q455 70 418 104\" stroke=\"var(--spe-pneumo)\" stroke-width=\"5\" fill=\"none\" stroke-linecap=\"round\"/>\n        <path d=\"M548 252 Q455 220 418 186\" stroke=\"var(--spe-pneumo)\" stroke-width=\"5\" fill=\"none\" stroke-linecap=\"round\"/>\n        <!-- libellés -->\n        <text x=\"375\" y=\"150\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"var(--ink-inverse)\"><span class=\"kw-clinique\">Nécrose</span></text>\n        <text x=\"375\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--spe-infectio)\">Pénombre</text>\n        <text x=\"110\" y=\"128\" text-anchor=\"middle\" font-size=\"12.5\" fill=\"var(--ink)\">Artère occluse</text>\n        <text x=\"222\" y=\"92\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\" fill=\"var(--spe-infectio)\"><span class=\"kw-etio\">thrombus</span></text>\n        <text x=\"546\" y=\"28\" text-anchor=\"end\" font-size=\"11.5\" fill=\"var(--spe-pneumo)\">collatérales</text>\n      </svg>\n      <div class=\"avc-schema__legend\">\n        <span><i style=\"background:var(--spe-mir)\"></i> Noyau — <span class=\"kw-clinique\">nécrose</span> <strong>irréversible</strong> (séquelles)</span>\n        <span><i style=\"background:var(--spe-infectio);opacity:.45\"></i> Pénombre — <strong>sauvable</strong> si <span class=\"kw-ttt\">reperfusion</span> précoce</span>\n        <span><i style=\"background:var(--spe-pneumo)\"></i> Suppléances (polygone de Willis)</span>\n      </div>\n      <figcaption>Plus la reperfusion est précoce, plus la pénombre est soustraite au noyau de nécrose. La qualité des collatérales conditionne la vitesse d'extension — d'où la variabilité clinique pour une même occlusion.</figcaption>\n    </figure>\n    <p>La vitesse d'extension de la <span class=\"kw-clinique\">nécrose</span> vers la pénombre dépend de la mise en jeu et de la qualité des suppléances artérielles (collatérales du polygone de Willis) — ce qui explique la variabilité du tableau clinique d'un patient à l'autre pour une même occlusion.</p>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-alerte\">poussée tensionnelle</span> à la phase aiguë est un mécanisme adaptatif maintenant la perfusion de la <span class=\"kw-clinique\">pénombre</span> : son <span class=\"kw-ci\">abaissement intempestif</span> peut <span class=\"kw-alerte\">étendre la nécrose</span>.</div>","frequence":3},{"id":"340-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les arguments cliniques diagnostiques en faveur des infarctus cérébraux constitués, accident ischémique transitoire, hémorragies intraparenchymateuses","contenu":"<p>Le tableau clinique d'un <span class=\"kw-def\">infarctus cérébral constitué</span> est systématisé à un territoire artériel : l'analyse sémiologique localise la <span class=\"kw-clinique\">lésion</span>. <span class=\"kw-alerte\">Seule l'imagerie</span> tranche entre nature <span class=\"kw-etio\">ischémique</span> et hémorragique.</p>\n    <figure class=\"obj-figure\">\n      <img src=\"../assets/images/340/territoires-vasculaires.png\" alt=\"Cartographie des territoires vasculaires cérébraux : circulation antérieure et postérieure\">\n      <figcaption>Territoires vasculaires cérébraux — circulation antérieure (système carotidien) et postérieure (système vertébro-basilaire).</figcaption>\n    </figure>\n    <table >\n      <thead><tr><th>Territoire</th><th>Signes cliniques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Ophtalmique</span></td><td><span class=\"kw-clinique\">Cécité monoculaire homolatérale</span> — pilier sémiologique de l'atteinte carotidienne ; transitoire = <span class=\"kw-def\">amaurose fugace</span> (<span class=\"kw-alerte\">AIT</span> carotidien typique)</td></tr>\n        <tr><td><span class=\"kw-def\">Cérébrale antérieure</span></td><td>Hémiplégie à prédominance crurale + troubles sensitifs ; apraxie idéomotrice de la main ; <span class=\"kw-clinique\">syndrome frontal</span> ; mutisme akinétique si atteinte bilatérale</td></tr>\n        <tr><td><span class=\"kw-def\">Sylvien superficiel</span></td><td>Déficit sensitivomoteur brachiofacial ; <span class=\"kw-clinique\">paralysie faciale</span> centrale ; HLH ;<br><strong>Hémisphère majeur (gauche) :</strong> <span class=\"kw-clinique\">aphasie de Broca</span> (antérieur), aphasie de Wernicke (postérieur), <span class=\"kw-clinique\">syndrome de Gerstmann</span> ;<br><strong>Hémisphère mineur (droit) :</strong> <span class=\"kw-clinique\">syndrome d'Anton-Babinski</span> (héminégligence, anosognosie, hémiasomatognosie)</td></tr>\n        <tr><td><span class=\"kw-def\">Sylvien profond</span></td><td><span class=\"kw-clinique\">Hémiplégie massive proportionnelle</span> (atteinte de la capsule interne)</td></tr>\n        <tr><td><span class=\"kw-def\">Sylvien total</span></td><td>Signes superficiels + profonds + déviation conjuguée de la tête et des yeux vers la <span class=\"kw-clinique\">lésion</span> + troubles de conscience initiaux</td></tr>\n        <tr><td><span class=\"kw-def\">Choroïdien antérieur</span></td><td>Syndrome des 3H controlatéral par atteinte du bras postérieur de la capsule interne : hémiplégie + hémianesthésie + hémianopsie latérale homonyme</td></tr>\n        <tr><td><span class=\"kw-def\">Occlusion carotidienne</span><br>(« T carotidien »)</td><td><span class=\"kw-clinique\">Infarctus</span> jonctionnels associant infarctus antérieur + sylvien ;<br><strong><span class=\"kw-def\">Syndrome optico-pyramidal</span> :</strong> cécité monoculaire homolatérale + hémiplégie controlatérale — <span class=\"kw-alerte\">signe une occlusion carotidienne homolatérale</span> à l'atteinte ophtalmique</td></tr>\n        <tr><td><span class=\"kw-def\">Cérébrale postérieure</span></td><td><strong>Superficiel :</strong> HLH souvent isolée, alexie ou agnosie visuelle ;<br><strong>Profond :</strong> syndrome thalamique (troubles sensitifs à tous les modes, douleurs neuropathiques de l'hémicorps controlatéral) ;<br><strong>Bilatéral complet :</strong> <span class=\"kw-alerte\">cécité corticale</span> et <span class=\"kw-clinique\">syndrome de Korsakoff</span> par atteinte bilatérale de la face interne des lobes temporaux (troubles mnésiques)</td></tr>\n        <tr><td><span class=\"kw-def\">Tronc cérébral</span></td><td><span class=\"kw-clinique\">Syndrome alterne</span> : atteinte d'un nerf crânien homolatéral + d'une voie longue controlatérale ; au maximum <span class=\"kw-alerte\">locked-in syndrome</span> par occlusion du tronc basilaire</td></tr>\n        <tr><td><span class=\"kw-def\">Wallenberg</span> (latérobulbaire)</td><td>Du côté de la <span class=\"kw-clinique\">lésion</span> : <span class=\"kw-clinique\">syndrome de Claude-Bernard-Horner</span>, hémisyndrome cérébelleux, atteinte du V, du IX et du X (<span class=\"kw-alerte\">fausses routes</span>), syndrome vestibulaire ; du côté opposé : hypoesthésie thermoalgique épargnant la face ; <span class=\"kw-alerte\">pas d'atteinte du VII</span></td></tr>\n        <tr><td><span class=\"kw-etio\">Lacunes</span></td><td>Petit <span class=\"kw-clinique\">infarctus</span> profond <span class=\"kw-chiffre\">&lt; 20 mm</span> (<span class=\"kw-etio\">lipohyalinose sur HTA</span>) : <span class=\"kw-clinique\">hémiplégie motrice pure</span>, hémianesthésie pure, dysarthrie-main malhabile, hémiparésie-hémiataxie ; fluctuation initiale évocatrice ;<br><strong><span class=\"kw-def\">État multilacunaire</span> :</strong> multiplication des petits infarctus profonds — syndrome pseudo-bulbaire (voix nasonnée, rires et pleurs spasmodiques), marche à petits pas, troubles sphinctériens, <span class=\"kw-alerte\">détérioration cognitive</span></td></tr>\n      </tbody>\n    </table>\n    <p><strong>Accident <span class=\"kw-etio\">ischémique</span> transitoire (<span class=\"kw-alerte\">AIT</span>)</strong> — épisode bref de dysfonction neurologique focale, d'origine ischémique cérébrale ou rétinienne, <span class=\"kw-alerte\">sans lésion en imagerie</span> ; installation en <span class=\"kw-chiffre\">&lt; 2 minutes</span>, durée typique <span class=\"kw-chiffre\">&lt; 1 h</span>. C'est un <span class=\"kw-def\">syndrome de menace cérébrale</span> : l'<span class=\"kw-alerte\">AIT</span> précède <span class=\"kw-chiffre\">30 %</span> des <span class=\"kw-clinique\">infarctus</span>, et <span class=\"kw-chiffre\">10 %</span> des patients font un infarctus constitué dans le mois (risque maximal dans les <span class=\"kw-chiffre\">premiers jours</span>).</p>\n    <table >\n      <thead><tr><th>Catégorie</th><th>Symptômes</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">AIT probable — carotidien</span></td><td>Cécité monoculaire (amaurose fugace) ; aphasie ; troubles moteurs et/ou sensitifs unilatéraux touchant la face et/ou les membres</td></tr>\n        <tr><td><span class=\"kw-def\">AIT probable — vertébrobasilaire</span></td><td>Troubles moteurs ou sensitifs bilatéraux ou à bascule ; HLH ; cécité corticale</td></tr>\n        <tr><td><span class=\"kw-def\">AIT possible</span></td><td>Symptômes compatibles mais non retenus seuls : <span class=\"kw-clinique\">vertige</span>, perte d'équilibre, diplopie, dysarthrie, troubles de la déglutition, sensitif isolé d'une partie de membre/hémiface, drop-attack (dérobement des jambes sans perte de conscience)</td></tr>\n        <tr><td><span class=\"kw-ci\">Non évocateurs d'AIT</span></td><td>Perte de connaissance, confusion, amnésie aiguë, faiblesse généralisée</td></tr>\n      </tbody>\n    </table>\n    <p><strong>Hémorragie intraparenchymateuse (HIP)</strong> — déficit <span class=\"kw-alerte\">non systématisé à un territoire artériel</span>, dépendant de la localisation de l'hématome ; aggravation en tache d'huile ; <span class=\"kw-clinique\">céphalées</span> plus fréquentes et plus sévères et troubles de la vigilance plus précoces que dans l'<span class=\"kw-clinique\">infarctus</span>, par <span class=\"kw-clinique\">hypertension intracrânienne</span> associée.</p>\n    <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Aucun argument clinique ne permet de différencier de façon fiable un <span class=\"kw-clinique\">infarctus</span> d'une hémorragie : <span class=\"kw-alerte\">l'imagerie cérébrale est indispensable</span> avant toute décision thérapeutique.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 92 — Déficit moteur-sensitif membres · 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":10,"liens":[{"href":"https://www.sfmu.org/calculateurs/ABCDD.html","label":"SFMU — Score ABCD² (AIT)"},{"href":"https://territoires-vasculaires-cerebraux.radioanatomie.com/","label":"Territoires vasculaires cérébraux (radioanatomie)"}]},{"id":"340-6","rang":"B","rubrique":"Diagnostic positif","titre":"Enumérer les arguments du diagnostic de dissection d'une artère à destinée cérébrale","contenu":"<p>La <span class=\"kw-def\">dissection d'une artère cervico-encéphalique</span> correspond au développement d'un <span class=\"kw-clinique\">hématome dans la paroi artérielle</span>, responsable d'une sténose (avec risque d'embole distal) voire d'une occlusion. C'est l'une des <span class=\"kw-alerte\">causes les plus fréquentes d'infarctus du sujet jeune</span> (environ <span class=\"kw-chiffre\">20 %</span>).</p>\n    <table >\n      <thead><tr><th>Volet</th><th>Arguments diagnostiques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Terrain</span></td><td><span class=\"kw-clinique\">Sujet jeune</span> ; survient le plus souvent sur artère saine ; contexte <span class=\"kw-etio\">post-traumatique</span> (<span class=\"kw-alerte\">choc</span>, hyperextension cervicale) ou <span class=\"kw-etio\">spontané</span> ; parfois <span class=\"kw-etio\">maladie du tissu conjonctif</span> (<span class=\"kw-etio\">Ehlers-Danlos</span>, <span class=\"kw-etio\">dysplasie fibromusculaire</span>)</td></tr>\n        <tr><td><span class=\"kw-def\">Triade clinique</span></td><td><strong>Signes ischémiques :</strong> selon le territoire artériel concerné ;<br><strong>Douleur :</strong> <span class=\"kw-clinique\">cervicalgie ou céphalée</span> — <span class=\"kw-clinique\">péri-orbitaire</span> si <span class=\"kw-etio\">dissection</span> carotidienne, <span class=\"kw-clinique\">postérieure</span> si dissection vertébrale ;<br><strong>Signes locaux homolatéraux :</strong> <span class=\"kw-clinique\">Claude-Bernard-Horner douloureux</span> (carotide), <span class=\"kw-clinique\">paralysie des nerfs crâniens bas IX-X-XI</span>, acouphène pulsatile</td></tr>\n        <tr><td><span class=\"kw-def\">Confirmation</span></td><td><span class=\"kw-imagerie\">Angio-IRM</span> ou <span class=\"kw-imagerie\">angio-TDM</span> des troncs supra-aortiques en <span class=\"kw-alerte\">urgence</span> : visualisation de l'<span class=\"kw-radio\">hématome de paroi</span> et de la <span class=\"kw-imagerie\">sténose</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Le traitement repose sur l'<span class=\"kw-ttt\">anticoagulation</span> ou un <span class=\"kw-ttt\">antiplaquettaire</span> pendant <span class=\"kw-chiffre\">3 à 6 mois</span>, jusqu'à <span class=\"kw-clinique\">cicatrisation de la paroi artérielle</span> ; <span class=\"kw-ci\">pas d'indication chirurgicale ou endovasculaire</span>. Mesures associées : <span class=\"kw-ci\">interdiction du sport et de la conduite</span> jusqu'à guérison, <span class=\"kw-clinique\">port d'un collier mousse</span> (pas de <span class=\"kw-ci\">contre-indication</span> par la suite).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 92 — Déficit moteur-sensitif membres</em></p>","frequence":1},{"id":"340-7","rang":"B","rubrique":"Diagnostic positif","titre":"Enumérer les arguments du diagnostic de thrombophlébite cérébrale","contenu":"<p>La <span class=\"kw-def\">thrombose veineuse cérébrale</span> (TVC, ou thrombophlébite cérébrale) représente <span class=\"kw-chiffre\">&lt; 2 %</span> des <span class=\"kw-alerte\">AVC</span>. Elle touche un ou plusieurs sinus veineux — le sinus longitudinal supérieur est le plus fréquemment atteint. L'<span class=\"kw-clinique\">infarctus veineux</span> éventuel ne correspond <span class=\"kw-alerte\">pas à un territoire artériel</span> et comporte souvent une composante <span class=\"kw-etio\">hémorragique</span>.</p>\n    <p>La <span class=\"kw-def\">triade clinique</span> évocatrice associe — souvent de façon incomplète, en mode aigu ou progressif sur quelques semaines :</p>\n    <ul>\n      <li><strong><span class=\"kw-clinique\">Céphalée</span></strong> — témoin de l'<span class=\"kw-clinique\">HTIC</span>, volontiers exacerbée à l'effort, <span class=\"kw-chiffre\">isolée dans 25 %</span> des cas, parfois avec <span class=\"kw-clinique\">œdème</span> papillaire.</li>\n      <li><strong><span class=\"kw-clinique\">Crises d'épilepsie</span></strong> — partielles ou généralisées ; les crises à bascule sont rares mais évocatrices.</li>\n      <li><strong><span class=\"kw-clinique\">Déficits neurologiques focaux</span></strong> — variables selon la localisation, parfois à bascule.</li>\n    </ul>\n    <table >\n      <thead><tr><th>Volet</th><th>Arguments</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Étiologies</span></td><td><strong>Hémostase :</strong> <span class=\"kw-etio\">contraception orale</span>, <span class=\"kw-etio\">thrombophilie congénitale ou acquise</span> ;<br><strong>Contextes :</strong> <span class=\"kw-etio\">grossesse et post-partum</span>, <span class=\"kw-etio\">période post-opératoire</span> ;<br><strong>Maladies générales :</strong> <span class=\"kw-etio\">maladie de Behçet</span>, <span class=\"kw-etio\">cancers</span>, <span class=\"kw-etio\">septicémie</span>, <span class=\"kw-etio\">déshydratation sévère</span> ;<br><strong>Causes locales :</strong> <span class=\"kw-etio\">infection de voisinage</span> (otite, sinusite, mastoïdite), <span class=\"kw-etio\">traumatisme</span>, <span class=\"kw-etio\">cathétérisme jugulaire</span></td></tr>\n        <tr><td><span class=\"kw-def\">Imagerie de référence</span></td><td><span class=\"kw-imagerie\">IRM cérébrale avec angio-IRM veineuse</span> : <span class=\"kw-radio\">sinus thrombosé</span>, <span class=\"kw-radio\">absence de flux</span> ; après gadolinium, <span class=\"kw-radio\">« signe du delta »</span> (prise de contraste de la paroi du sinus)</td></tr>\n      </tbody>\n    </table>\n    <figure class=\"obj-figure\">\n      <img src=\"../assets/images/340/tvc-veinoirm-transverse.png\" alt=\"Veino-IRM montrant une thrombose du sinus transverse droit\">\n      <figcaption>Veino-<span class=\"kw-imagerie\">IRM</span> — thrombose du sinus transverse droit (absence de flux dans le sinus occlus).</figcaption>\n    </figure>\n    <figure class=\"obj-figure\">\n      <img src=\"../assets/images/340/tvc-longitudinal-superieur.png\" alt=\"Imagerie d'une thrombose du sinus longitudinal supérieur\">\n      <figcaption>Thrombose du sinus longitudinal supérieur — sinus le plus fréquemment atteint.</figcaption>\n    </figure>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-ttt\">traitement anticoagulant</span> (<span class=\"kw-ttt\">héparine</span> en <span class=\"kw-alerte\">urgence</span> puis relais <span class=\"kw-ttt\">AVK</span> <span class=\"kw-chiffre\">≥ 6 mois</span>) doit être instauré <span class=\"kw-alerte\">même en présence d'un infarctus hémorragique</span> — l'hémorragie n'est <span class=\"kw-ci\">pas une contre-indication</span> ici.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée · 105 — Epilepsie</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/cerebral-venous-thrombosis","label":"Radiopaedia : Cerebral venous thrombosis"},{"href":"https://radiopaedia.org/articles/dural-venous-sinuses","label":"Radiopaedia : Dural venous sinuses"}]},{"id":"340-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes de gravité d'un AVC","contenu":"<p>Les <span class=\"kw-def\">signes de gravité</span> d'un <span class=\"kw-alerte\">AVC</span> <span class=\"kw-alerte\">engagent le pronostic vital</span> et orientent vers une prise en charge en <span class=\"kw-alerte\">soins intensifs</span> ou en réanimation. Ils tiennent à l'étendue de la <span class=\"kw-clinique\">lésion</span>, à sa localisation et à ses complications.</p>\n    <table >\n      <thead><tr><th>Domaine</th><th><span class=\"kw-alerte\">Signes de gravité</span></th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Conscience</span></td><td><span class=\"kw-alerte\">Troubles de la vigilance</span> ; <span class=\"kw-alerte\">coma</span> — par <span class=\"kw-clinique\">lésion</span> directe du tronc cérébral ou par effet de <span class=\"kw-clinique\">masse</span></td></tr>\n        <tr><td><span class=\"kw-def\">Sévérité du déficit</span></td><td>Déficit massif, <span class=\"kw-clinique\">score NIHSS élevé</span> ; atteinte motrice bilatérale</td></tr>\n        <tr><td><span class=\"kw-def\">Topographie / occlusion</span></td><td><span class=\"kw-alerte\">Occlusion du tronc basilaire</span> (<span class=\"kw-alerte\">coma</span>, <span class=\"kw-clinique\">locked-in syndrome</span>) ; occlusion artérielle proximale</td></tr>\n        <tr><td><span class=\"kw-def\">Infarctus cérébral malin</span></td><td><span class=\"kw-clinique\">Infarctus</span> sylvien total du sujet jeune : <span class=\"kw-clinique\">œdème</span> cytotoxique et <span class=\"kw-alerte\">HTIC entre 24 et 72 h</span>, risque d'<span class=\"kw-alerte\">engagement</span> ;<br><span class=\"kw-ttt\">craniectomie de décompression</span> réservée aux patients <span class=\"kw-chiffre\">&lt; 60 ans</span> + <span class=\"kw-chiffre\">NIHSS &gt; 16</span> + <span class=\"kw-clinique\">troubles de la vigilance</span></td></tr>\n        <tr><td><span class=\"kw-def\">Spécificités HIP</span></td><td>Hématome volumineux ; effet de <span class=\"kw-clinique\">masse</span>, risque d'<span class=\"kw-alerte\">engagement temporal</span> ; inondation ventriculaire et <span class=\"kw-alerte\">hydrocéphalie aiguë</span></td></tr>\n        <tr><td><span class=\"kw-def\">Fosse postérieure</span></td><td><span class=\"kw-clinique\">Infarctus ou hématome cérébelleux</span> : <span class=\"kw-alerte\">compression du tronc cérébral</span> et du 4ᵉ ventricule</td></tr>\n        <tr><td><span class=\"kw-def\">Complications</span></td><td><span class=\"kw-alerte\">Transformation hémorragique</span> ; <span class=\"kw-clinique\">pneumopathie d'inhalation</span> sur troubles de la déglutition (Wallenberg) ; <span class=\"kw-alerte\">état de mal épileptique</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute <span class=\"kw-alerte\">modification de l'état neurologique</span> à la phase précoce justifie une <span class=\"kw-imagerie\">TDM cérébrale de contrôle</span> en urgence (extension de l'ischémie, transformation <span class=\"kw-etio\">hémorragique</span>, hydrocéphalie).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1},{"id":"340-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d'AVC ischémiques","contenu":"<p>Les <span class=\"kw-def\">causes d'infarctus cérébral</span> se répartissent en quatre grands cadres, dont l'identification conditionne la <span class=\"kw-def\">prévention secondaire</span>. L'origine reste indéterminée dans <span class=\"kw-chiffre\">25 %</span> des cas.</p>\n    <table >\n      <thead><tr><th>Cause</th><th>Part</th><th>Caractéristiques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-etio\">Athérosclérose</span> (macroangiopathie)</td><td><span class=\"kw-chiffre\">~30 %</span></td><td><span class=\"kw-clinique\">Sténose <span class=\"kw-chiffre\">&gt; 50 %</span></span> en amont de l'<span class=\"kw-clinique\">infarctus</span> + <span class=\"kw-def\">facteurs de risque</span> vasculaire ; mécanisme thromboembolique, <span class=\"kw-etio\">thrombotique</span> ou hémodynamique</td></tr>\n        <tr><td><span class=\"kw-etio\">Cardiopathies emboligènes</span></td><td><span class=\"kw-chiffre\">~20 %</span></td><td>Évoquées devant des <span class=\"kw-clinique\">infarctus</span> de <span class=\"kw-clinique\">territoires artériels différents</span> ; la <span class=\"kw-etio\">fibrillation atriale</span> est de loin la première cause (<span class=\"kw-chiffre\">50 %</span>)</td></tr>\n        <tr><td><span class=\"kw-etio\">Lacunes</span> (microangiopathie)</td><td><span class=\"kw-chiffre\">~20 %</span></td><td>Occlusion d'une artériole profonde par <span class=\"kw-etio\">lipohyalinose</span> ; principal <span class=\"kw-def\">facteur de risque</span> = <span class=\"kw-alerte\">HTA</span></td></tr>\n        <tr><td><span class=\"kw-etio\">Dissection</span> cervico-encéphalique</td><td>—</td><td>Cause majeure de l'<span class=\"kw-clinique\">infarctus du sujet jeune</span></td></tr>\n        <tr><td><span class=\"kw-etio\">Causes rares</span></td><td>—</td><td><span class=\"kw-etio\">États prothrombotiques</span> (Vaquez, SAPL, <span class=\"kw-alerte\">CIVD</span>), <span class=\"kw-etio\">artérites</span> (Horton), <span class=\"kw-etio\">maladies métaboliques</span> (drépanocytose, Fabry, mitochondriopathies)</td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Le mécanisme cardio-<span class=\"kw-etio\">embolique</span> est <span class=\"kw-alerte\">systématiquement évoqué</span> devant des <span class=\"kw-clinique\">infarctus</span> simultanés ou distincts dans des <span class=\"kw-clinique\">territoires artériels différents</span> (ex. infarctus cortico-sous-corticaux bilatéraux).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span class=\"kw-clinique\">Fibrillation</span> atriale · 152 — Endocardites infectieuses · 222 — FDR cardiovasculaire</em></p>","frequence":1},{"id":"340-10","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d'AVC hémorragiques","contenu":"<p>Les <span class=\"kw-def\">causes d'hémorragie intraparenchymateuse</span> dépendent de l'âge du patient et de la <span class=\"kw-clinique\">topographie de l'hématome</span> : une HIP profonde évoque l'<span class=\"kw-etio\">HTA</span>, une HIP lobaire du sujet âgé évoque l'<span class=\"kw-etio\">angiopathie amyloïde</span>.</p>\n    <table >\n      <thead><tr><th>Cause</th><th>Fréquence</th><th>Caractéristiques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-etio\">Microangiopathie hypertensive</span></td><td><span class=\"kw-chiffre\">~50 %</span></td><td><span class=\"kw-alerte\">Rupture</span> des artérioles perforantes sur <span class=\"kw-etio\">HTA chronique</span> ; HIP <span class=\"kw-clinique\">typiquement profonde</span> : capsulo-thalamique, capsulo-lenticulaire, cérébelleuse</td></tr>\n        <tr><td><span class=\"kw-etio\">Troubles de l'hémostase</span></td><td><span class=\"kw-chiffre\">&gt; 10 %</span></td><td><span class=\"kw-etio\">Acquis</span> (<span class=\"kw-etio\">anticoagulants</span>, alcoolisme) ou congénitaux (hémophilie) ; les <span class=\"kw-alerte\">anticoagulants oraux</span> sont responsables de <span class=\"kw-chiffre\">10 %</span> des HIP</td></tr>\n        <tr><td><span class=\"kw-etio\">Malformations vasculaires</span></td><td><span class=\"kw-chiffre\">5–10 %</span></td><td><span class=\"kw-etio\">MAV</span>, <span class=\"kw-etio\">cavernome</span> ; <span class=\"kw-chiffre\">≥ 1/3</span> des HIP du sujet jeune</td></tr>\n        <tr><td><span class=\"kw-etio\">Tumeurs cérébrales</span></td><td><span class=\"kw-chiffre\">5–10 %</span></td><td>Surtout malignes (métastases de rein et de <span class=\"kw-clinique\">mélanome</span>, glioblastome) ; l'HIP est souvent <span class=\"kw-clinique\">révélatrice</span></td></tr>\n        <tr><td><span class=\"kw-etio\">Angiopathie amyloïde</span></td><td>—</td><td>Sujet âgé : HIP <span class=\"kw-clinique\">lobaires récidivantes</span>, associées à un déficit cognitif</td></tr>\n      </tbody>\n    </table>\n    <figure class=\"obj-figure\">\n      <img src=\"../assets/images/340/hip-lobaire-irm.png\" alt=\"IRM d'un hématome lobaire\">\n      <figcaption>Hématome lobaire en <span class=\"kw-imagerie\">IRM</span> — topographie superficielle évocatrice d'angiopathie amyloïde chez le sujet âgé, ou de malformation vasculaire chez le sujet jeune.</figcaption>\n    </figure>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une <span class=\"kw-imagerie\">imagerie vasculaire</span> (<span class=\"kw-imagerie\">angio-TDM</span> ou <span class=\"kw-imagerie\">angio-IRM</span>) est indiquée devant une HIP <span class=\"kw-alerte\">lobaire chez un sujet jeune non hypertendu</span>, des symptômes neurologiques précédant l'HIP, ou une <span class=\"kw-clinique\">HSA associée</span> — l'<span class=\"kw-etio\">HTA</span> donne des HIP <span class=\"kw-clinique\">profondes</span>.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 341 — Hémorragie méningée</em></p>","frequence":1},{"id":"340-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d'explorations complémentaires à la phase aigüe d'un AVC","contenu":"<p>À la phase aiguë, la priorité est de <span class=\"kw-alerte\">confirmer l'AVC et de trancher entre ischémie et hémorragie</span> en <span class=\"kw-alerte\">urgence</span>, sans retarder la <span class=\"kw-ttt\">revascularisation</span>. Trois gestes systématiques accompagnent l'imagerie : <span class=\"kw-alerte\">noter l'heure de début</span>, <span class=\"kw-bio\">glycémie capillaire</span>, <span class=\"kw-bio\">bilan biologique standard</span> et <span class=\"kw-clinique\">ECG</span>.</p>\n    <figure class=\"avc-flow\" role=\"img\" aria-label=\"Arbre d'orientation à la phase aiguë : devant une suspicion d'AVC, réaliser une imagerie cérébrale en urgence — IRM en première intention, TDM sans injection si IRM indisponible. En cas d'hyperdensité spontanée, il s'agit d'un AVC hémorragique orientant vers un bilan d'hémostase et une imagerie vasculaire. En l'absence d'hémorragie, il s'agit d'un AVC ischémique orientant vers l'angiographie des troncs supra-aortiques et la revascularisation en urgence.\">\n      <div class=\"avc-flow__node node--start\">Suspicion d'<span class=\"kw-alerte\">AVC</span> <small>déficit neurologique focal brutal</small></div>\n      <div class=\"avc-flow__arrow\">↓</div>\n      <div class=\"avc-flow__node node--exam\">Imagerie cérébrale en <span class=\"kw-alerte\">urgence</span> <small><span class=\"kw-imagerie\">IRM</span> 1ʳᵉ intention (DWI · FLAIR · T2* · TOF) — <span class=\"kw-imagerie\">TDM</span> sans injection si <span class=\"kw-imagerie\">IRM</span> indisponible</small></div>\n      <div class=\"avc-flow__split\">\n        <div class=\"avc-flow__branch\">\n          <div class=\"avc-flow__q\">Hyperdensité spontanée ?</div>\n          <div class=\"avc-flow__node node--hem\"><span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">hémorragique</span> (HIP) <small>bilan d'hémostase · <span class=\"kw-imagerie\">angio-TDM</span>/<span class=\"kw-imagerie\">IRM</span> si lobaire ou sujet jeune</small></div>\n        </div>\n        <div class=\"avc-flow__branch\">\n          <div class=\"avc-flow__q\">Pas d'hémorragie</div>\n          <div class=\"avc-flow__node node--isch\"><span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span> <small>angio des TSA · <span class=\"kw-ttt\">revascularisation</span> en <span class=\"kw-alerte\">urgence</span> si dans la fenêtre</small></div>\n        </div>\n      </div>\n    </figure>\n    <table >\n      <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n      <tbody>\n        <tr>\n          <td><span class=\"kw-imagerie\">IRM cérébrale</span><br>(examen de référence)</td>\n          <td>\n            <strong>4 séquences obligatoires :</strong> <span class=\"kw-imagerie\">diffusion</span> (DWI), <span class=\"kw-imagerie\">T2/FLAIR</span>, <span class=\"kw-imagerie\">T2*</span> (écho de gradient), <span class=\"kw-imagerie\">TOF</span> (<span class=\"kw-imagerie\">angio-IRM</span> cérébrale) ;<br>\n            <strong>Perfusion :</strong> <span class=\"kw-imagerie\">non obligatoire</span> pour un <span class=\"kw-clinique\">infarctus</span> pris en charge en <span class=\"kw-chiffre\">&lt; 6 h</span> ;<br>\n            <strong>Complément :</strong> <span class=\"kw-imagerie\">angio-IRM des troncs supra-aortiques</span> (<span class=\"kw-imagerie\">thrombus</span>, <span class=\"kw-imagerie\">sténose</span>)\n          </td>\n        </tr>\n        <tr>\n          <td><span class=\"kw-imagerie\">TDM cérébrale sans injection</span><br>(alternative si <span class=\"kw-imagerie\">IRM</span> indisponible)</td>\n          <td>\n            Élimine immédiatement une hémorragie (<span class=\"kw-radio\">hyperdensité spontanée</span>) ;<br>\n            <strong>Complément :</strong> <span class=\"kw-imagerie\">angio-TDM des troncs supra-aortiques</span> et du <span class=\"kw-imagerie\">polygone de Willis</span>\n          </td>\n        </tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La séquence <span class=\"kw-ci\">T2 simple ne fait pas partie du protocole AVC</span> — c'est la séquence <span class=\"kw-imagerie\">T2*</span> qui recherche la <span class=\"kw-clinique\">composante hémorragique</span>. <span class=\"kw-ci\">Pas d'aspirine systématique avant l'imagerie</span>, même devant une suspicion d'<span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span>.</div>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/circle-of-willis","label":"Radiopaedia : Circle of Willis"}]},{"id":"340-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan étiologique de première ligne d'un AVC ischémique et d'un AVC hémorragique","contenu":"<p>Une fois l'<span class=\"kw-alerte\">AVC</span> confirmé et son type établi, le <span class=\"kw-def\">bilan étiologique de première ligne</span> oriente la <span class=\"kw-def\">prévention secondaire</span>. Il diffère selon la nature <span class=\"kw-etio\">ischémique</span> ou hémorragique.</p>\n    <table >\n      <thead><tr><th>Type d'<span class=\"kw-alerte\">AVC</span></th><th>Bilan étiologique de <span class=\"kw-chiffre\">première ligne</span></th></tr></thead>\n      <tbody>\n        <tr>\n          <td><span class=\"kw-def\">AVC ischémique</span></td>\n          <td>\n            <strong>Cœur :</strong> <span class=\"kw-clinique\">ECG</span> dès l'admission, scope puis <span class=\"kw-imagerie\">Holter-ECG</span> si négatif, voire <span class=\"kw-imagerie\">Holter</span> implantable si forte suspicion de <span class=\"kw-etio\">FA paroxystique</span> ; <span class=\"kw-imagerie\">ETT</span> puis <span class=\"kw-imagerie\">ETO</span> si suspicion cardio-<span class=\"kw-etio\">embolique</span> ;<br>\n            <strong>Vaisseaux :</strong> <span class=\"kw-imagerie\">angio-TDM ou angio-IRM des TSA</span>, ou <span class=\"kw-imagerie\">écho-Doppler des TSA</span> + <span class=\"kw-imagerie\">Doppler transcrânien</span> ;<br>\n            <strong>Biologie :</strong> <span class=\"kw-bio\">NFS-plaquettes, TP-TCA</span> (état prothrombotique), <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">bilan lipidique</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">CRP</span> ;<br>\n            <strong>Causes rares (au cas par cas) :</strong> <span class=\"kw-bio\">AAN</span>, <span class=\"kw-bio\">homocystéinémie</span>, <span class=\"kw-bio\">hémostase complète</span> (thrombophilie), <span class=\"kw-bio\">ponction lombaire</span> (artérite cérébrale)\n          </td>\n        </tr>\n        <tr>\n          <td><span class=\"kw-def\">AVC hémorragique</span></td>\n          <td>\n            <strong>Hémostase :</strong> <span class=\"kw-bio\">NFS-plaquettes, TP, TCA</span> ;<br>\n            <strong>Imagerie :</strong> <span class=\"kw-imagerie\">IRM cérébrale</span> ; <span class=\"kw-imagerie\">angio-TDM ou angio-IRM</span> en l'absence d'argument pour une cause hypertensive (suspicion de <span class=\"kw-etio\">MAV</span>) ;<br>\n            <strong>À distance :</strong> <span class=\"kw-imagerie\">IRM avec séquence T2*</span> (recherche de <span class=\"kw-etio\">cavernome</span>, d'<span class=\"kw-etio\">angiopathie amyloïde</span>)\n          </td>\n        </tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-ci\">angiographie conventionnelle n'a pas sa place en première intention</span> ; elle se discute en seconde intention devant une suspicion forte de <span class=\"kw-etio\">lésion vasculaire</span> accessible à un traitement (<span class=\"kw-etio\">MAV</span>, anévrisme, <span class=\"kw-clinique\">fistule</span> durale).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span class=\"kw-clinique\">Fibrillation</span> atriale · 222 — FDR cardiovasculaire</em></p>","frequence":3},{"id":"340-13","rang":"B","rubrique":"Contenu multimédia","titre":"IRM d'un AVC ischémique en phase aiguë","contenu":"<p>L'<span class=\"kw-imagerie\">IRM</span> est l'examen de référence de l'<span class=\"kw-clinique\">infarctus</span> cérébral en phase aiguë : elle confirme l'ischémie, en date l'ancienneté et recherche l'<span class=\"kw-imagerie\">occlusion artérielle</span>.</p>\n    <figure class=\"obj-figure\">\n      <img src=\"../assets/images/340/ischemique-dwi-sylvien.png\" alt=\"IRM de diffusion : infarctus sylvien en hypersignal\">\n      <figcaption>Séquence de diffusion (DWI) — infarctus sylvien en hypersignal systématisé à un territoire artériel.</figcaption>\n    </figure>\n    <table >\n      <thead><tr><th>Séquence</th><th>Sémiologie de l'infarctus aigu</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-imagerie\">Diffusion (DWI)</span></td><td><span class=\"kw-radio\">Hypersignal</span> systématisé à un territoire artériel dès les <span class=\"kw-chiffre\">premières minutes</span> ; la <span class=\"kw-imagerie\">séquence la plus sensible</span> ; permet la mesure du volume infarci</td></tr>\n        <tr><td><span class=\"kw-imagerie\">ADC</span></td><td><span class=\"kw-radio\">Hyposignal (noir)</span> en regard — confirme l'<span class=\"kw-clinique\">œdème cytotoxique</span> de l'ischémie récente</td></tr>\n        <tr><td><span class=\"kw-imagerie\">T2/FLAIR</span></td><td><span class=\"kw-radio\">Hypersignal</span> apparaissant vers <span class=\"kw-chiffre\">4 h 30</span> ; reste <span class=\"kw-imagerie\">normale au tout début</span> de l'ischémie</td></tr>\n        <tr><td><span class=\"kw-imagerie\">T2*</span></td><td>Recherche une <span class=\"kw-clinique\">composante hémorragique</span> ou un remaniement (en <span class=\"kw-radio\">hyposignal</span>)</td></tr>\n        <tr><td><span class=\"kw-imagerie\">TOF</span> (<span class=\"kw-imagerie\">angio-IRM</span>)</td><td>Visualise l'<span class=\"kw-imagerie\">occlusion artérielle</span> sur le <span class=\"kw-imagerie\">polygone de Willis</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-def\">mismatch DWI-FLAIR</span> — <span class=\"kw-radio\">hypersignal en diffusion</span> alors que le <span class=\"kw-imagerie\">FLAIR est encore normal</span> — date l'ischémie à <span class=\"kw-chiffre\">&lt; 4 h 30</span> : il permet de poser une indication de <span class=\"kw-ttt\">thrombolyse</span> même lorsque l'heure de début est inconnue.</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/ischemic-stroke-2","label":"Radiopaedia : Ischemic stroke"}]},{"id":"340-14","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d'un AVC hémorragique profond en phase aiguë","contenu":"<p>La <span class=\"kw-imagerie\">TDM cérébrale sans injection</span> affirme l'<span class=\"kw-clinique\">hémorragie intraparenchymateuse</span> dès la phase aiguë et en précise la topographie. L'hématome apparaît en <span class=\"kw-radio\">hyperdensité spontanée</span> dès les <span class=\"kw-chiffre\">premières heures</span>.</p>\n    <figure class=\"obj-figure\">\n      <img src=\"../assets/images/340/hip-profond-tdm.png\" alt=\"TDM d'une hémorragie intraparenchymateuse profonde\">\n      <figcaption><span class=\"kw-imagerie\">TDM</span> sans injection — hématome profond en hyperdensité spontanée, topographie évocatrice d'une microangiopathie hypertensive.</figcaption>\n    </figure>\n    <table >\n      <thead><tr><th>Élément</th><th>Description</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Densité</span></td><td><span class=\"kw-radio\">Hyperdensité spontanée</span> dès les premières heures, <span class=\"kw-imagerie\">sans injection de produit de contraste</span></td></tr>\n        <tr><td><span class=\"kw-def\">Topographie profonde</span></td><td>Capsulo-thalamique, capsulo-lenticulaire ou cérébelleuse — évocatrice d'une <span class=\"kw-etio\">microangiopathie hypertensive</span></td></tr>\n        <tr><td><span class=\"kw-def\">Retentissement</span></td><td>Recherche d'un <span class=\"kw-alerte\">effet de masse</span>, d'une inondation ventriculaire, d'une hydrocéphalie</td></tr>\n        <tr><td><span class=\"kw-def\">Complément</span></td><td><span class=\"kw-imagerie\">Angio-TDM</span> réalisable dans la foulée si une <span class=\"kw-etio\">cause vasculaire</span> est suspectée</td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Une HIP <span class=\"kw-clinique\">profonde</span> chez un patient hypertendu connu oriente d'emblée vers la <span class=\"kw-etio\">cause hypertensive</span> ; une localisation <span class=\"kw-clinique\">lobaire</span> ou un <span class=\"kw-clinique\">sujet jeune non hypertendu</span> imposent une <span class=\"kw-imagerie\">imagerie vasculaire</span> complémentaire.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/intracerebral-hemorrhage-1","label":"Radiopaedia : Intracerebral hemorrhage"}]},{"id":"340-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les actions à réaliser lors de la phase pré-hospitalière","contenu":"<p>La <span class=\"kw-def\">phase pré-hospitalière</span> conditionne l'accès aux <span class=\"kw-ttt\">traitements de revascularisation</span> : chaque minute compte. L'objectif est d'acheminer le patient vers une <span class=\"kw-clinique\">filière neurovasculaire</span> sans perte de temps.</p>\n    <table >\n      <thead><tr><th>Action</th><th>Modalités</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Alerter</span></td><td><span class=\"kw-clinique\">Contact du 15 sans délai</span> pour tout symptôme évocateur (critères <span class=\"kw-def\">FAST</span>)</td></tr>\n        <tr><td><span class=\"kw-def\">Noter l'heure</span></td><td><span class=\"kw-alerte\">Heure de début des symptômes</span> et mode d'installation — détermine l'<span class=\"kw-clinique\">éligibilité aux traitements</span></td></tr>\n        <tr><td><span class=\"kw-def\">Transport</span></td><td>Transport non médicalisé en règle ; médicalisé seulement en cas de <span class=\"kw-alerte\">trouble de la vigilance</span> ou de <span class=\"kw-alerte\">défaillance cardio-respiratoire</span></td></tr>\n        <tr><td><span class=\"kw-def\">Orienter</span></td><td>Centre disposant d'une <span class=\"kw-imagerie\">imagerie cérébrale</span> et d'un neurologue (ou télémédecine) ; information préhospitalière de l'équipe hospitalière</td></tr>\n        <tr><td><span class=\"kw-def\">Mesures initiales</span></td><td>Position avec <span class=\"kw-clinique\">tête à 30°</span> ; maintien de la normoglycémie et de la normothermie</td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> <span class=\"kw-ci\">Ne pas administrer d'antihypertenseur</span> à la phase pré-hospitalière, sauf chiffres tensionnels extrêmes (<span class=\"kw-chiffre\">&gt; 220/120 mmHg</span> pour un <span class=\"kw-clinique\">infarctus</span>). <span class=\"kw-ci\">Pas d'aspirine</span> avant l'imagerie : la nature <span class=\"kw-etio\">ischémique</span> ou hémorragique n'est <span class=\"kw-alerte\">pas encore établie</span>.</div>","frequence":1},{"id":"340-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge à la phase aigüe de l'AVC ischémique","contenu":"<p>La prise en charge de l'<span class=\"kw-def\">infarctus cérébral</span> à la phase aiguë se déroule en unité neurovasculaire et combine la <span class=\"kw-ttt\">revascularisation</span>, le <span class=\"kw-ttt\">traitement antithrombotique</span> et les mesures générales.</p>\n    <figure class=\"avc-frise\" role=\"img\" aria-label=\"Frise des fenêtres thérapeutiques de revascularisation de l'infarctus cérébral : de 0 à 4h30 thrombolyse intraveineuse possible (avec thrombectomie associée) ; de 4h30 à 6h thrombectomie mécanique sur occlusion proximale ; jusqu'à 24h thrombectomie sur imagerie de sélection (mismatch). Time is brain : le bénéfice décroît avec le temps écoulé.\">\n      <div class=\"avc-frise__head\"><b>⏱ Time is brain</b> — chaque minute d'ischémie détruit ~2 millions de neurones</div>\n      <div class=\"avc-frise__track\">\n        <div class=\"avc-frise__seg seg--1\">\n          <span class=\"w\"><span class=\"kw-ttt\">Thrombolyse</span> IV <small>± thrombectomie</small></span>\n          <b class=\"t\"><span class=\"kw-chiffre\">0 h</span><small>début</small></b>\n        </div>\n        <div class=\"avc-frise__seg seg--2\">\n          <span class=\"w\">Thrombectomie <small>occlusion proximale</small></span>\n          <b class=\"t\"><span class=\"kw-chiffre\">4 h</span> 30</b>\n        </div>\n        <div class=\"avc-frise__seg seg--3\">\n          <span class=\"w\">Thrombectomie sur sélection <small>mismatch imagerie</small></span>\n          <b class=\"t\"><span class=\"kw-chiffre\">6 h</span></b>\n          <b class=\"t end\"><span class=\"kw-chiffre\">24 h</span></b>\n        </div>\n      </div>\n    </figure>\n    <table >\n      <thead><tr><th>Traitement</th><th>Indications &amp; modalités</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-ttt\">Thrombolyse IV</span><br>(altéplase, <span class=\"kw-imagerie\">rt</span>-PA)</td><td>Délai <span class=\"kw-chiffre\">&lt; 4 h 30</span> après l'installation des signes ; <span class=\"kw-radio\">mismatch FLAIR-diffusion</span> si horaire indéterminé ; <span class=\"kw-alerte\">contre-indications nombreuses</span> — décision par un <span class=\"kw-clinique\">spécialiste neurovasculaire</span> ; risque d'<span class=\"kw-alerte\">hémorragie cérébrale</span> et d'<span class=\"kw-alerte\">angiœdème</span></td></tr>\n        <tr><td><span class=\"kw-ttt\">Thrombectomie mécanique</span><br>(voie endovasculaire)</td><td>Délai <span class=\"kw-chiffre\">&lt; 6 h</span>, extensible jusqu'à <span class=\"kw-chiffre\">24 h</span> sur mismatch ; uniquement si <span class=\"kw-clinique\">occlusion proximale</span> (tronc carotidien, <span class=\"kw-clinique\">M1/M2 de la cérébrale moyenne</span>, tronc basilaire) ; seule ou en complément de la <span class=\"kw-ttt\">thrombolyse</span></td></tr>\n        <tr><td><span class=\"kw-ttt\">Antithrombotiques</span></td><td><span class=\"kw-ttt\">Aspirine</span> <span class=\"kw-chiffre\">160–300 mg/jour</span> — dès l'arrivée en l'absence de <span class=\"kw-ttt\">thrombolyse</span>, ou après l'<span class=\"kw-imagerie\">imagerie de contrôle à 24 h</span> si thrombolyse réalisée ; <span class=\"kw-ttt\">clopidogrel</span> si <span class=\"kw-ci\">contre-indication</span></td></tr>\n        <tr><td><span class=\"kw-ttt\">Prévention de la MTEV</span></td><td><span class=\"kw-ttt\">Héparine à doses isocoagulantes</span> (<span class=\"kw-ttt\">HBPM</span> en l'absence d'<span class=\"kw-ci\">insuffisance rénale</span>) en cas d'alitement</td></tr>\n        <tr><td><span class=\"kw-def\">Mesures générales</span></td><td><span class=\"kw-clinique\">Respect de la poussée tensionnelle</span> (traitement seulement si <span class=\"kw-chiffre\">&gt; 220/120</span>, ou <span class=\"kw-chiffre\">&gt; 185/110</span> si <span class=\"kw-ttt\">revascularisation</span>) ; lutte contre l'<span class=\"kw-clinique\">hyperthermie</span> et l'hyperglycémie ; tête à 30°, pas de lever ; recherche systématique de <span class=\"kw-alerte\">troubles de la déglutition</span></td></tr>\n        <tr><td><span class=\"kw-def\">Œdème cérébral</span></td><td><span class=\"kw-ttt\">Macromolécules</span> (<span class=\"kw-ttt\">mannitol</span>) ; lutte contre hypercapnie et hyponatrémie ; <span class=\"kw-ttt\">craniectomie de décompression</span> si <span class=\"kw-alerte\">infarctus malin</span> ; <span class=\"kw-ci\">pas de corticoïdes</span> (inutiles et délétères sur l'<span class=\"kw-clinique\">œdème</span> cytotoxique)</td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-warn\"><strong>Piège classique.</strong> En phase aiguë d'<span class=\"kw-clinique\">infarctus</span>, on <span class=\"kw-ci\">respecte l'hypertension artérielle</span> : un abaissement intempestif <span class=\"kw-alerte\">menace</span> la <span class=\"kw-clinique\">zone de pénombre</span>. Les <span class=\"kw-ci\">corticoïdes sont inutiles et délétères</span> sur l'<span class=\"kw-clinique\">œdème</span> cytotoxique.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/endovascular-clot-retrieval-ecr","label":"Radiopaedia : Endovascular clot retrieval (ECR)"},{"href":"https://www.youtube.com/watch?v=CBGagjAq9B0","label":"YouTube — Thrombectomie mécanique"}]},{"id":"340-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mesures mise en œuvre dans la prévention primaire et secondaire","contenu":"<p>La <span class=\"kw-def\">prévention</span> agit sur les <span class=\"kw-etio\">facteurs de risque</span> et sur la cause identifiée. La <span class=\"kw-def\">prévention primaire</span> précède tout événement ; la <span class=\"kw-def\">prévention secondaire</span> suit un premier <span class=\"kw-alerte\">AVC</span> et dépend de l'étiologie.</p>\n    <table >\n      <thead><tr><th>Cadre</th><th>Mesures</th></tr></thead>\n      <tbody>\n        <tr>\n          <td><span class=\"kw-def\">Prévention primaire</span></td>\n          <td>\n            <strong><span class=\"kw-def\">Facteurs de risque</span> :</strong> contrôle de l'<span class=\"kw-etio\">HTA</span> (objectif <span class=\"kw-chiffre\">&lt; 140/90 mmHg</span>), du <span class=\"kw-etio\">diabète</span>, de la <span class=\"kw-etio\">dyslipidémie</span> ; <span class=\"kw-ttt\">sevrage</span> du tabac et de l'alcool ; activité physique régulière ;<br>\n            <strong><span class=\"kw-etio\">Fibrillation atriale</span> :</strong> <span class=\"kw-ttt\">anticoagulant oral</span> si <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">CHA₂DS₂-VASc ≥ 1</span> ;<br>\n            <strong>Sténose carotide asymptomatique :</strong> <span class=\"kw-ttt\">endartériectomie</span> discutée si <span class=\"kw-chiffre\">&gt; 60 %</span>\n          </td>\n        </tr>\n        <tr>\n          <td><span class=\"kw-def\">Prévention secondaire</span> — <span class=\"kw-clinique\">infarctus</span> athérothrombotique</td>\n          <td>\n            <span class=\"kw-ttt\">Antiplaquettaire</span> (<span class=\"kw-ttt\">aspirine</span> ou <span class=\"kw-ttt\">clopidogrel</span>) ; <span class=\"kw-ttt\">statine</span> ; contrôle tensionnel strict (objectif <span class=\"kw-chiffre\">PA &lt; 140/90 mmHg</span>) ; <span class=\"kw-clinique\">sevrage tabagique</span> ;<br>\n            <strong>Sténose carotide symptomatique :</strong> <span class=\"kw-ttt\">endartériectomie</span> si <span class=\"kw-chiffre\">&gt; 70 %</span> (discutée entre <span class=\"kw-chiffre\">50 et 70 %</span>), dans les <span class=\"kw-chiffre\">15 jours</span>\n          </td>\n        </tr>\n        <tr>\n          <td><span class=\"kw-def\">Prévention secondaire</span> — autres causes</td>\n          <td>\n            <strong><span class=\"kw-etio\">Fibrillation atriale</span> :</strong> <span class=\"kw-ttt\">anticoagulant oral</span> — <span class=\"kw-ttt\">anti-Xa</span> ou <span class=\"kw-ttt\">anti-IIa</span> en <span class=\"kw-chiffre\">première intention</span>, <span class=\"kw-ci\">contre-indiqués si FA valvulaire</span> ;<br>\n            <strong><span class=\"kw-etio\">Dissection</span> :</strong> <span class=\"kw-ttt\">anticoagulant</span> ou <span class=\"kw-ttt\">antiplaquettaire</span> <span class=\"kw-chiffre\">3 à 6 mois</span> ;<br>\n            <strong>HIP :</strong> traitement de l'<span class=\"kw-etio\">HTA</span>, correction d'un trouble de l'hémostase, traitement d'une <span class=\"kw-etio\">malformation vasculaire</span>\n          </td>\n        </tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-clinique\">contrôle des 9 facteurs de risque</span> <span class=\"kw-alerte\">réduit de 90 %</span> le risque d'<span class=\"kw-alerte\">AVC</span>. L'<span class=\"kw-ci\">association de deux antiplaquettaires au long cours</span> n'apporte pas de bénéfice et majore le risque <span class=\"kw-etio\">hémorragique</span>.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 224 — <span class=\"kw-etio\">HTA</span> · 247 — Diabète · 223 — Dyslipidémie · 232 — <span class=\"kw-clinique\">Fibrillation</span> atriale · 75 — Addiction Tabac · 76 — Addiction à l'alcool</em></p>","frequence":4},{"id":"340-18","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic fonctionnel et vital des AVC","contenu":"<p>L'<span class=\"kw-alerte\">AVC</span> est la <span class=\"kw-alerte\">1ʳᵉ cause de handicap acquis de l'adulte</span> et la <span class=\"kw-chiffre\">3ᵉ cause de mortalité</span>. Le <span class=\"kw-def\">pronostic</span>, toujours difficile à établir à la phase aiguë, impose la prudence dans l'information délivrée.</p>\n    <table >\n      <thead><tr><th>Domaine</th><th>Données pronostiques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Pronostic vital</span></td><td><span class=\"kw-def\">Mortalité</span> globale <span class=\"kw-chiffre\">~25 %</span> (<span class=\"kw-chiffre\">20 %</span> à<span class=\"kw-chiffre\"> 1 mois</span>, <span class=\"kw-chiffre\">40 %</span> à<span class=\"kw-chiffre\"> 1 an</span>) ; <span class=\"kw-alerte\">mortalité de l'HIP &gt; 50 % dans les 3 premiers jours</span> ; surmortalité à distance liée au risque coronarien</td></tr>\n        <tr><td><span class=\"kw-def\">Pronostic fonctionnel</span></td><td>Environ <span class=\"kw-chiffre\">75 %</span> des patients gardent une séquelle ; règle des tiers parmi les survivants : <span class=\"kw-chiffre\">1/3</span> dépendants, <span class=\"kw-chiffre\">1/3</span> séquelles avec autonomie, <span class=\"kw-chiffre\">1/3</span> retour à l'état antérieur</td></tr>\n        <tr><td><span class=\"kw-def\">Récupération</span></td><td><span class=\"kw-chiffre\">70 %</span> de la récupération dans les <span class=\"kw-chiffre\">3 premiers mois</span>, se poursuivant jusqu'à <span class=\"kw-chiffre\">6 mois</span> ; proportionnelle à la sévérité initiale</td></tr>\n        <tr><td><span class=\"kw-def\">Score NIHSS</span> initial</td><td>Coté de <span class=\"kw-chiffre\">0 à 42</span> : NIHSS <span class=\"kw-chiffre\">&lt; 7</span> = bon <span class=\"kw-def\">pronostic</span> ; <span class=\"kw-chiffre\">7–16</span> = intermédiaire ; <span class=\"kw-alerte\">&gt; 16 = mauvais pronostic</span></td></tr>\n        <tr><td><span class=\"kw-def\">Facteurs péjoratifs</span></td><td>Âge avancé ; <span class=\"kw-clinique\">troubles de la vigilance</span> ; volume lésionnel ; inondation ventriculaire ; <span class=\"kw-clinique\">hyperthermie</span>, hyperglycémie ; <span class=\"kw-etio\">diabète</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Les <span class=\"kw-clinique\">déficiences</span> sont motrices (hémiplégie, déglutition), sensorielles (hémianopsie) et cognitives (aphasie, négligence) ; l'<span class=\"kw-alerte\">AVC</span> est la <span class=\"kw-chiffre\">2ᵉ cause</span> de <span class=\"kw-alerte\">troubles cognitifs majeurs</span>, et expose à la dépression post-AVC et à l'épilepsie vasculaire.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 108 — Confusion, démence du sujet âgé · 105 — Epilepsie</em></p>","frequence":3},{"id":"340-19","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes de l'évaluation du rapport bénéfice/risque de la prise en charge d'un patient atteint d'AVC","contenu":"<p>Le <span class=\"kw-def\">rapport bénéfice/risque</span> de chaque investigation et de chaque traitement est évalué selon l'<span class=\"kw-clinique\">état clinique du patient</span>. Le <span class=\"kw-def\">pronostic</span> étant difficile à établir à la phase aiguë, la décision se construit de façon prudente et partagée.</p>\n    <ul>\n      <li><strong>Évaluation pluridisciplinaire</strong> — <span class=\"kw-clinique\">concertation</span> entre <span class=\"kw-clinique\">neurologues</span>, <span class=\"kw-clinique\">réanimateurs</span> et <span class=\"kw-clinique\">neurochirurgiens</span>, intégrant les <span class=\"kw-clinique\">arguments pronostiques neurologiques</span> et l'origine d'une éventuelle <span class=\"kw-alerte\">défaillance viscérale</span>.</li>\n      <li><strong>Éléments pris en compte</strong> — <span class=\"kw-clinique\">autonomie antérieure</span> à l'<span class=\"kw-alerte\">AVC</span>, <span class=\"kw-clinique\">état neurologique</span>, <span class=\"kw-clinique\">comorbidités</span>, <span class=\"kw-clinique\">âge</span>.</li>\n      <li><strong>Directives anticipées</strong> — en cas d'<span class=\"kw-alerte\">évolution défavorable</span>, les <span class=\"kw-def\">directives anticipées</span> définies par le patient avant l'<span class=\"kw-alerte\">AVC</span> sont prises en compte.</li>\n      <li><strong>Information</strong> — information <span class=\"kw-clinique\">claire et loyale</span> du patient et de sa <span class=\"kw-def\">personne de confiance</span> sur les décisions thérapeutiques, les investigations et le <span class=\"kw-def\">pronostic</span> fonctionnel.</li>\n    </ul>\n    <div class=\"callout callout-info\"><strong>À retenir.</strong> Toute décision de prise en charge en <span class=\"kw-alerte\">réanimation</span> est prise de façon <span class=\"kw-alerte\">collégiale</span> ; le rapport bénéfice/risque s'apprécie au cas par cas, en évitant l'<span class=\"kw-alerte\">obstination déraisonnable</span> comme la <span class=\"kw-alerte\">perte de chance</span>.</div>","frequence":0}],"astuces":[{"type":"danger","titre":"Time is brain — 1,9 million de neurones / minute","contenu":"Chaque minute d'occlusion artérielle = 1,9 million de neurones perdus, 14 milliards de synapses, 12 km d'axones myélinisés. Chaque minute gagnée en thrombolyse = 4 jours de vie en bonne santé en plus. Appel 15 immédiat, IRM en urgence, UNV."},{"type":"warn","titre":"FAST = Face-Arm-Speech-Time","contenu":"L'échelle FAST permet au grand public de reconnaître un AVC : asymétrie faciale (faire sourire), déficit du bras (lever les deux bras), trouble de la parole (faire répéter une phrase). Si l'un de ces signes est positif → appeler le 15."},{"type":"tip","titre":"Mismatch DWI-FLAIR pour wake-up strokes","contenu":"Si le patient se réveille avec un déficit (heure de début inconnue), l'IRM peut sauver la thrombolyse : DWI positif + FLAIR négatif = ischémie < 4h30 → thrombolyse possible (essai WAKE-UP). Sinon, attendre la thrombectomie selon le mismatch perfusion."},{"type":"danger","titre":"PAS d'aspirine avant l'imagerie","contenu":"Tant que l'imagerie n'a pas éliminé une hémorragie, aucun antithrombotique ne doit être donné. L'aspirine est introduite dans les 48 h après confirmation ischémique, différée de 24 h si thrombolyse réalisée."},{"type":"info","titre":"Dissection chez le sujet jeune","contenu":"Sujet < 50 ans + AVC + cervicalgie + syndrome de Claude-Bernard-Horner = dissection carotidienne jusqu'à preuve du contraire. Diagnostic : angio-IRM avec coupes axiales T1 Fat-Sat (hyper-signal en croissant = hématome de paroi)."},{"type":"warn","titre":"HIP lobaire du sujet âgé = angiopathie amyloïde","contenu":"Une HIP lobaire (cortico-sous-corticale) chez un sujet âgé > 75 ans + microbleeds en T2* = angiopathie amyloïde. Risque de récidive majeur → contre-indication formelle aux anticoagulants à vie."}],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span> <span class=\"q\">— fenêtre de <span class=\"kw-ttt\">reperfusion</span></span></strong></p><p><span class=\"kw-imagerie\">imagerie cérébrale</span> sans délai ; <span class=\"kw-alerte\">noter l’heure de début</span> des symptômes</p><ul><li>« <span class=\"kw-def\">Time is brain</span> » : chaque minute d’ischémie détruit <span class=\"kw-chiffre\">2 millions de neurones</span></li><li><span class=\"kw-ttt\">Thrombolyse IV</span> (<span class=\"kw-imagerie\">rt</span>-PA) possible si <span class=\"kw-chiffre\">&lt; 4 h 30</span> après le début</li><li><span class=\"kw-ttt\">Thrombectomie mécanique</span> si <span class=\"kw-clinique\">occlusion proximale</span> dans les <span class=\"kw-chiffre\">&lt; 6 h</span> (jusqu’à <span class=\"kw-chiffre\">24 h</span> si mismatch)</li></ul><p><strong><span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">hémorragique</span></strong></p><p><span class=\"kw-imagerie\">TDM sans injection</span> : <span class=\"kw-imagerie\">hyperdensité spontanée</span> immédiate</p><ul><li><span class=\"kw-ttt\">Baisse précoce de la PA</span> (<span class=\"kw-chiffre\">&lt; 6 h</span>, PAS cible <span class=\"kw-chiffre\">140-160 mmHg</span>) pour limiter l’expansion de l’hématome</li><li><span class=\"kw-ttt\">Antagonisation en urgence</span> si <span class=\"kw-etio\">anticoagulant</span> en cours</li></ul><p><strong><span class=\"kw-alerte\">AIT</span> <span class=\"q\">— syndrome de <span class=\"kw-alerte\">menace</span> cérébral</span></strong></p><p>bilan et <span class=\"kw-ttt\">prévention secondaire</span> en <span class=\"kw-alerte\">urgence</span>, même symptômes régressifs</p><ul><li>Précède <span class=\"kw-chiffre\">30 %</span> des <span class=\"kw-clinique\">infarctus</span> cérébraux</li><li><span class=\"kw-alerte\">10 % feront un infarctus dans le mois</span>, risque maximal les premiers jours</li></ul>","hospit":"<p><strong>Pré-hospitalier :</strong> <span class=\"kw-clinique\">contact du 15 sans délai</span> ; transport <em>non</em> médicalisé (médicalisé seulement si <span class=\"kw-alerte\">trouble de la vigilance</span> ou <span class=\"kw-alerte\">défaillance cardio-respiratoire</span>) ; information préhospitalière des acteurs (neurologue, urgentiste, radiologue).<br><strong>Orientation :</strong> <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-def\">unité neurovasculaire (UNV)</span> systématique — quels que soient l’âge, le sexe et la gravité (<span class=\"kw-def\">AIT</span> comme <span class=\"kw-alerte\">AVC</span> grave). Réduit la morbi-<span class=\"kw-def\">mortalité</span> : <span class=\"kw-chiffre\">1 décès ou 1 handicap évité pour 20 patients</span>.<br><strong><span class=\"kw-alerte\">Réanimation</span> / neurochirurgie :</strong> <span class=\"kw-alerte\">coma</span> (<span class=\"kw-ttt\">intubation</span> pour protéger les VAS) ; <span class=\"kw-alerte\">infarctus malin</span> (<span class=\"kw-ttt\">craniectomie</span> de décompression si <span class=\"kw-chiffre\">&lt; 60 ans</span> + <span class=\"kw-chiffre\">NIHSS &gt; 16</span>) ; <span class=\"kw-alerte\">hématome / infarctus cérébelleux compressif</span> (évacuation, dérivation).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Trouble de la vigilance</span> / <span class=\"kw-alerte\">coma</span> (évaluer le <span class=\"kw-def\">Glasgow</span> du côté sain)</li><li><span class=\"kw-alerte\">Occlusion du tronc basilaire</span> : <span class=\"kw-alerte\">coma</span> brutal, atteinte des nerfs crâniens, <span class=\"kw-alerte\">locked-in syndrome</span></li><li><span class=\"kw-alerte\">Aggravation neurologique</span> à la phase précoce → <span class=\"kw-imagerie\">TDM de contrôle</span> (extension / transformation <span class=\"kw-etio\">hémorragique</span>)</li><li><span class=\"kw-alerte\">Infarctus cérébral malin</span> : sylvien total, sujet jeune, <span class=\"kw-alerte\">HTIC à 24-72 h</span> par <span class=\"kw-clinique\">œdème</span> cytotoxique</li><li>Signes d’<span class=\"kw-alerte\">HTIC</span> (<span class=\"kw-clinique\">céphalées</span>, vomissements, troubles de conscience), risque d’<span class=\"kw-alerte\">engagement temporal</span></li><li><span class=\"kw-alerte\">Inondation ventriculaire</span> / <span class=\"kw-alerte\">hydrocéphalie aiguë</span> (hématome ou <span class=\"kw-clinique\">infarctus</span> cérébelleux)</li><li><span class=\"kw-clinique\">Troubles de la déglutition</span> → <span class=\"kw-alerte\">pneumopathie d’inhalation</span> (syndrome de <span class=\"kw-etio\">Wallenberg</span> ++)</li><li>HIP : pathologie plus grave que l’ischémie — <span class=\"kw-alerte\">mortalité &gt; 50 % dans les 3 premiers jours</span></li></ul>","principes":"<p><strong>Règle d’or :</strong> <span class=\"kw-alerte\">seule l’imagerie autorise le traitement spécifique</span> — elle tranche <span class=\"kw-def\">ischémique</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">hémorragique</span>. <span class=\"kw-ttt\">Reperfusion</span> la plus précoce possible + mesures générales (<span class=\"kw-def\">A₂C₂SOS</span>) + prévention des complications. <span class=\"kw-ci\">Pas d’aspirine avant l’imagerie</span>.</p><p><strong>Mesures générales communes</strong></p><ul><li>Alitement <span class=\"kw-clinique\">tête à 30°</span> ; <span class=\"kw-ci\">pas de lever à la phase aiguë</span></li><li>Lutte contre l’<span class=\"kw-clinique\">hyperthermie</span> (<span class=\"kw-ttt\">paracétamol</span> si T° <span class=\"kw-chiffre\">&gt; 38 °C</span>) ; <span class=\"kw-bio\">glycémie</span> (<span class=\"kw-ttt\">insuline</span> SC si <span class=\"kw-chiffre\">&gt; 1,8 g/L</span>, <span class=\"kw-ttt\">glucosé</span> si <span class=\"kw-chiffre\">&lt; 0,5 g/L</span>) ; <span class=\"kw-ttt\">O₂</span> si SaO₂ <span class=\"kw-chiffre\">&lt; 95 %</span></li><li><span class=\"kw-clinique\">Dépistage des troubles de déglutition</span> (sonde gastrique si besoin) ; <span class=\"kw-ttt\">kinésithérapie</span> motrice précoce ; prévention <span class=\"kw-def\">MTEV</span></li></ul><p><strong><span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span></strong></p><ul><li><span class=\"kw-ttt\">Thrombolyse IV</span> (<span class=\"kw-imagerie\">rt</span>-PA / altéplase) si <span class=\"kw-chiffre\">&lt; 4 h 30</span> ; <span class=\"kw-ttt\">thrombectomie</span> si occlusion proximale</li><li><span class=\"kw-ttt\">Aspirine 160-300 mg/j</span> dès l’arrivée — ou au décours de l’<span class=\"kw-imagerie\">imagerie de contrôle à 24 h</span> si <span class=\"kw-ttt\">thrombolyse</span> ; <span class=\"kw-ttt\">clopidogrel</span> si CI</li><li>Respect de la poussée tensionnelle : traiter (<span class=\"kw-ttt\">nicardipine</span> / <span class=\"kw-ttt\">urapidil</span> IVSE) seulement si <span class=\"kw-chiffre\">&gt; 220/120 mmHg</span> (<span class=\"kw-chiffre\">&gt; 185/110</span> si <span class=\"kw-ttt\">reperfusion</span>)</li></ul><p><strong><span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">hémorragique</span> (HIP)</strong></p><ul><li><span class=\"kw-ci\">Aucun traitement spécifique</span> hormis l’<span class=\"kw-ttt\">antagonisation</span> d’un <span class=\"kw-ttt\">anticoagulant</span> (<span class=\"kw-ttt\">PPSB + vit. K</span> / <span class=\"kw-ttt\">idarucizumab</span> / <span class=\"kw-ttt\">andexanet alfa</span>)</li><li>PAS cible <span class=\"kw-chiffre\">140-160 mmHg</span> précoce ; <span class=\"kw-ci\">pas de corticoïdes</span> (<span class=\"kw-clinique\">œdème</span> cytotoxique) ; <span class=\"kw-ttt\">neurochirurgie</span> si hématome compressif</li></ul><p><strong>Thrombose veineuse cérébrale</strong></p><ul><li><span class=\"kw-ttt\">Héparinothérapie en urgence</span> — <span class=\"kw-alerte\">même en cas d’infarctus hémorragique</span></li><li>Relais <span class=\"kw-ttt\">AVK</span> <span class=\"kw-chiffre\">≥ 6 mois</span> + traitement étiologique (foyer <span class=\"kw-etio\">infectieux</span>, arrêt contraception)</li></ul>","suivi":"<p><strong>Phase aiguë :</strong> <span class=\"kw-def\">NIHSS</span> répété (toute aggravation → <span class=\"kw-imagerie\">réimagerie</span>), scope, <span class=\"kw-def\">surveillance</span> <span class=\"kw-def\">A₂C₂SOS</span> (PA, <span class=\"kw-bio\">glycémie</span>, T°, O₂, <span class=\"kw-bio\">natrémie</span>).<br><strong>Prévention 2aire — <span class=\"kw-etio\">ischémique</span> :</strong> <span class=\"kw-ttt\">antiplaquettaire</span> (<span class=\"kw-etio\">athérome</span> / cause indéterminée) ; <span class=\"kw-ttt\">anticoagulant</span> si <span class=\"kw-etio\">FA</span> (<span class=\"kw-ttt\">AOD</span> en 1ʳᵉ intention, ou <span class=\"kw-ttt\">AVK</span> <span class=\"kw-chiffre\">INR 2-3</span>) ; <span class=\"kw-ttt\">endartériectomie</span> si sténose carotide symptomatique <span class=\"kw-chiffre\">&gt; 70 %</span> (<span class=\"kw-chiffre\">&lt; 15 j</span>) ; contrôle des <span class=\"kw-etio\">FRCV</span> (<span class=\"kw-chiffre\">PA &lt; 140/90</span>, <span class=\"kw-bio\">LDL &lt; 0,55 g/L</span>, <span class=\"kw-bio\">HbA1c &lt; 7 %</span>).<br><strong>Prévention 2aire — <span class=\"kw-etio\">hémorragique</span> :</strong> traiter l’<span class=\"kw-etio\">étiologie</span> (<span class=\"kw-etio\">HTA</span>, malformation vasculaire, trouble de la coagulation).<br><strong>Rééducation :</strong> <span class=\"kw-chiffre\">70 % de la récupération</span> dans les <span class=\"kw-chiffre\">3 premiers mois</span> ; MPR <span class=\"kw-chiffre\">intensive 4-5×/semaine</span> ; kiné, orthophonie, ergothérapie.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">20 % à 1 mois</span>, <span class=\"kw-chiffre\">40 % à 1 an</span> ; <span class=\"kw-def\">NIHSS initial</span> prédictif. <span class=\"kw-def\">Suivi</span> à <span class=\"kw-chiffre\">2-6 mois</span> puis <span class=\"kw-chiffre\">1 an</span> ; commission médicale du permis avant reprise de la conduite.</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/accidents-vasculaires-cerebraux","label":"Collège (CEN) — Accidents vasculaires cérébraux"},{"href":"https://campus.neurochirurgie.fr/article1788.html","label":"Campus neurochirurgie — AVC"},{"href":"https://www.sfmu.org/calculateurs/NIHSS.html","label":"SFMU — Score NIHSS"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Déficit neurologique focal brutal, maximal d’emblée — Imagerie cérébrale en urgence (TDM sans injection ou IRM) — seule l’imagerie tranche ischémique vs hémorragique","detail":"<h4>CAT — <span class=\"kw-alerte\">AVC</span> à la phase aiguë — De l’imagerie au traitement de <span class=\"kw-ttt\">reperfusion</span> / antagonisation</h4>","branches":[{"to":"q-delai","label":"AVC ischémique (TDM normale ou hypodensité, pas de saignement)","color":"blue"},{"to":"q-iatro","label":"AVC hémorragique (hyperdensité spontanée à l’imagerie)","color":"red"}]},{"id":"q-delai","kind":"decision","label":"Délai depuis le début des symptômes <span class=\"kw-chiffre\">< 4</span> h 30 et pas de <span class=\"kw-ci\">contre-indication</span> à la thrombolyse ? — heure de début notée ; mismatch FLAIR-diffusion si horaire indéterminé","branches":[{"to":"q-occl-tl","label":"Oui — éligible à la thrombolyse IV","color":"amber"},{"to":"q-occl-te","label":"Non — > 4 h 30 ou CI à la thrombolyse","color":"amber"}]},{"id":"q-occl-tl","kind":"decision","label":"Occlusion proximale + NIHSS <span class=\"kw-chiffre\">> 4,</span> dans les < 6 h ? — tronc carotidien, <span class=\"kw-chiffre\">M1</span> / M2 proximale de la cérébrale moyenne, tronc basilaire","branches":[{"to":"t-tl-te","label":"Oui — occlusion proximale accessible","color":"amber"},{"to":"t-tl","label":"Non","color":"amber"}]},{"id":"t-tl-te","kind":"terminal","label":"Thrombolyse IV + thrombectomie mécanique","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Occlusion proximale</span> (tronc carotidien, <span class=\"kw-chiffre\">M1</span>/M2 proximale, tronc basilaire) + <span class=\"kw-chiffre\">NIHSS &gt; 4</span>, début <span class=\"kw-chiffre\">&lt; 6 h</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Thrombolyse IV (rt-PA / altéplase)</span> si <span class=\"kw-chiffre\">&lt; 4 h 30</span></li><li><span class=\"kw-ttt\">Thrombectomie mécanique</span> (<span class=\"kw-ttt\">stent</span> retriever et/ou thromboaspiration) en complément</li></ul><h4>Tension</h4><ul><li>PA <span class=\"kw-chiffre\">&lt; 185/110 mmHg</span> avant, maintenue <span class=\"kw-chiffre\">&lt; 180/105 mmHg</span> pendant <span class=\"kw-chiffre\">24 h</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">Imagerie de contrôle à 24 h</span> avant tout <span class=\"kw-ttt\">antithrombotique</span></li></ul>"},{"id":"t-tl","kind":"terminal","label":"Thrombolyse IV seule","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Thrombolyse IV (rt-PA / altéplase)</span> dans les <span class=\"kw-chiffre\">&lt; 4 h 30</span> — décision par un médecin spécialisé en pathologie neurovasculaire (<span class=\"kw-ci\">contre-indications nombreuses</span>)</li></ul><h4>Risques</h4><ul><li><span class=\"kw-alerte\">Hémorragie cérébrale</span> et hémorragie systémique (gastrique)</li><li><span class=\"kw-alerte\">Angiœdème</span>, surtout chez les patients sous <span class=\"kw-ttt\">IEC</span></li></ul><h4>Suites</h4><ul><li><span class=\"kw-ttt\">Antithrombotiques</span> au décours de l’<span class=\"kw-imagerie\">imagerie de contrôle à 24 h</span> ; PA <span class=\"kw-chiffre\">&lt; 180/105 mmHg</span></li></ul>"},{"id":"q-occl-te","kind":"decision","label":"Occlusion proximale + NIHSS <span class=\"kw-chiffre\">> 4,</span> dans les < 6 h (jusqu’à 24 h si mismatch) ? — mismatch perfusion-diffusion jusqu’à 16 h, mismatch clinico-radiologique jusqu’à 24 h","branches":[{"to":"t-te","label":"Oui","color":"amber"},{"to":"t-antithrombo","label":"Non","color":"green"}]},{"id":"t-te","kind":"terminal","label":"Thrombectomie mécanique seule","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Occlusion proximale</span> + <span class=\"kw-chiffre\">NIHSS &gt; 4</span> en présence d’une <span class=\"kw-ci\">contre-indication à la thrombolyse</span></li></ul><h4>Fenêtre</h4><ul><li><span class=\"kw-chiffre\">&lt; 6 h</span> ; jusqu’à <span class=\"kw-chiffre\">16 h</span> si mismatch perfusion-diffusion, <span class=\"kw-chiffre\">24 h</span> si mismatch clinico-radiologique</li></ul><h4>Tension</h4><ul><li>PA <span class=\"kw-chiffre\">&lt; 180/105 mmHg</span> avant et pendant <span class=\"kw-chiffre\">24 h</span></li></ul>"},{"id":"t-antithrombo","kind":"terminal","label":"Pas de reperfusion → antithrombotiques","color":"green","detail":"<h4>Situation</h4><ul><li>Hors fenêtre de <span class=\"kw-ttt\">reperfusion</span> ou absence d’occlusion proximale accessible</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Aspirine 160-300 mg/j</span> dès l’arrivée (<span class=\"kw-ci\">pas avant l’imagerie</span>) ; <span class=\"kw-ttt\">clopidogrel</span> si CI à l’<span class=\"kw-ttt\">aspirine</span></li><li>Prévention <span class=\"kw-def\">MTEV</span> : <span class=\"kw-ttt\">HBPM à dose isocoagulante</span> (en l’absence d’IRC)</li></ul><h4>Tension</h4><ul><li>Respect de la poussée tensionnelle ; ne traiter que si <span class=\"kw-chiffre\">&gt; 220/120 mmHg</span></li></ul>"},{"id":"q-iatro","kind":"decision","label":"Hémorragie iatrogène — patient sous anticoagulant ? — AVK · anti-IIa (dabigatran) · anti-Xa oral (apixaban, rivaroxaban)","branches":[{"to":"t-antago","label":"Oui — AVK / anti-IIa / anti-Xa","color":"red"},{"to":"t-hip-mesures","label":"Non","color":"amber"}]},{"id":"t-antago","kind":"terminal","label":"Antagonisation en urgence","color":"red","detail":"<h4>Si <span class=\"kw-ttt\">AVK</span></h4><ul><li><span class=\"kw-ttt\">PPSB</span> + <span class=\"kw-ttt\">vitamine K</span> adaptés au poids</li></ul><h4>Si anti-IIa (<span class=\"kw-ttt\">dabigatran</span>)</h4><ul><li><span class=\"kw-ttt\">Idarucizumab</span> en <span class=\"kw-alerte\">urgence</span> ; à défaut <span class=\"kw-ttt\">PPSB</span></li></ul><h4>Si anti-Xa oral (<span class=\"kw-ttt\">apixaban</span>, <span class=\"kw-ttt\">rivaroxaban</span>)</h4><ul><li><span class=\"kw-ttt\">Andexanet alfa</span> en <span class=\"kw-alerte\">urgence</span> ; à défaut <span class=\"kw-ttt\">PPSB</span> ou <span class=\"kw-ttt\">FEIBA</span></li></ul><h4>Mesures associées</h4><ul><li><span class=\"kw-ttt\">Baisse précoce de la PA</span> (PAS cible <span class=\"kw-chiffre\">140-160 mmHg</span>, <span class=\"kw-chiffre\">&lt; 6 h</span>)</li><li><span class=\"kw-ci\">Pas de corticoïdes</span> ; <span class=\"kw-ttt\">neurochirurgie</span> si hématome compressif</li></ul>"},{"id":"t-hip-mesures","kind":"terminal","label":"Pas de traitement spécifique → mesures générales","color":"amber","detail":"<h4>Principe</h4><ul><li><span class=\"kw-ci\">Aucun traitement spécifique des HIP</span> en dehors de l’antagonisation d’un <span class=\"kw-ttt\">anticoagulant</span></li></ul><h4>Tension</h4><ul><li><span class=\"kw-ttt\">Baisse de la PA</span> précoce (PAS cible <span class=\"kw-chiffre\">140-160 mmHg</span>, <span class=\"kw-chiffre\">&lt; 6 h</span>) pour prévenir l’expansion de l’hématome</li></ul><h4>Prévention MTEV</h4><ul><li><span class=\"kw-ttt\">Contention pneumatique intermittente</span> (référence) ou <span class=\"kw-ttt\">HBPM isocoagulante</span> débutée à <span class=\"kw-chiffre\">24 h</span></li></ul><h4>Neurochirurgie</h4><ul><li>Discutée si <span class=\"kw-alerte\">hématome cérébelleux</span> avec trouble de la vigilance, ou <span class=\"kw-alerte\">hydrocéphalie aiguë</span> ; <span class=\"kw-ci\">pas de corticoïdes</span></li></ul><h4>Prévention 2aire</h4><ul><li>Traiter l’<span class=\"kw-etio\">étiologie</span> : <span class=\"kw-etio\">HTA</span>, malformation vasculaire, trouble de la coagulation</li></ul>"}]},"cards":[{"i":"1a70d455c63d","n":340,"o":"340-1","u":"Définition","t":"Connaître la définition et la classification des accidents vasculaires cérébraux (AVC)","q":"Comment l'OMS définit-elle un accident vasculaire cérébral (AVC) ?","a":"<p>Selon l'OMS, un AVC est un développement rapide de <strong>signes de dysfonction cérébrale durant plus de 24 heures</strong> (ou conduisant au décès), sans autre cause apparente qu'une origine vasculaire.</p>"},{"i":"3a49cd9161e2","n":340,"o":"340-1","u":"Définition","t":"Connaître la définition et la classification des accidents vasculaires cérébraux (AVC)","q":"Quels sont les trois caractères sémiologiques fondamentaux permettant de diagnostiquer un accident vasculaire cérébral (AVC) ?","a":"<ul><li><strong>Focal</strong> : la perte de fonction correspond à la lésion d'une structure anatomique donnée (ex: motricité, sensibilité, vision, langage).</li><li><strong>Brutal</strong> : déficit maximal d'emblée, sans prodrome, d'intensité maximale en <strong>moins de 2 minutes</strong>.</li><li><strong>Déficitaire</strong> : seules les pertes de fonction comptent ; toute manifestation productive (clonies, phosphènes, mouvements anormaux) doit faire remettre en cause le diagnostic.</li></ul>"},{"i":"7e81185573d3","n":340,"o":"340-1","u":"Définition","t":"Connaître la définition et la classification des accidents vasculaires cérébraux (AVC)","q":"Comment les accidents vasculaires cérébraux (AVC) sont-ils classifiés selon leur type et leur mécanisme ?","a":"<ul><li><strong>AVC ischémique</strong> (environ 80 %) :</li><ul><li>Infarctus cérébral constitué : nécrose du parenchyme par occlusion artérielle.</li><li>Accident ischémique transitoire (AIT) : ischémie focale brève, sans lésion en imagerie.</li></ul><li><strong>AVC hémorragique</strong> (environ 20 %) :</li><ul><li>Hémorragie intraparenchymateuse (HIP) : saignement dans le parenchyme (environ 15 %).</li><li>Hémorragie sous-arachnoïdienne (HSA) : saignement méningé (environ 5 %).</li></ul><li><strong>Thrombose veineuse cérébrale</strong> (moins de 2 %) : occlusion d'un sinus ou d'une veine cérébrale, n'obéissant pas à un territoire artériel.</li></ul>"},{"i":"afb32885d1d9","n":340,"o":"340-1","u":"Définition","t":"Connaître la définition et la classification des accidents vasculaires cérébraux (AVC)","q":"Quelles pathologies sont exclues de la définition d'un accident vasculaire cérébral (AVC) ?","a":"<p>Sont exclus du cadre de l'AVC : les <strong>syncopes</strong> et <strong>malaises sans déficit focal</strong>, ainsi que les <strong>ischémies globales par bas débit</strong>.</p>"},{"i":"bbe9b6fe6add","n":340,"o":"340-1","u":"Définition","t":"Connaître la définition et la classification des accidents vasculaires cérébraux (AVC)","q":"Quelle est la définition générale d'un accident vasculaire cérébral (AVC) ?","a":"<p>Un AVC est un <strong>déficit neurologique focal d'installation brutale</strong>, dû à une lésion du parenchyme cérébral d'origine vasculaire.</p>"},{"i":"1223f37edf87","n":340,"o":"340-10","u":"Étiologies","t":"Connaître les principales causes d'AVC hémorragiques","q":"Quelle est la principale étiologie des hémorragies intraparenchymateuses (HIP) et quelles en sont les caractéristiques principales ?","a":"<p>La principale étiologie est la <strong>microangiopathie hypertensive</strong>, responsable d'environ 50 % des cas. Elle résulte de la rupture des artérioles perforantes sur une hypertension artérielle (HTA) chronique. Les HIP sont typiquement <strong>profondes</strong> (capsulo-thalamique, capsulo-lenticulaire, cérébelleuse).</p>"},{"i":"9828141e53cc","n":340,"o":"340-10","u":"Étiologies","t":"Connaître les principales causes d'AVC hémorragiques","q":"Quelles sont les autres causes d'hémorragie intraparenchymateuse à connaître, en dehors de l'HTA et des troubles de l'hémostase ?","a":"<ul><li>Les <strong>malformations vasculaires</strong> (MAV, cavernome) : 5-10 % des cas, particulièrement chez le sujet jeune (plus d'un tiers des HIP du sujet jeune).</li><li>Les <strong>tumeurs cérébrales</strong> (5-10 %) : surtout malignes (métastases de rein et de mélanome, glioblastome), l'HIP étant souvent révélatrice.</li><li>L'<strong>angiopathie amyloïde</strong> : chez le sujet âgé, entraînant des HIP lobaires récidivantes, souvent associées à un déficit cognitif.</li></ul>"},{"i":"a10f51b81214","n":340,"o":"340-10","u":"Étiologies","t":"Connaître les principales causes d'AVC hémorragiques","q":"Comment l'âge du patient et la topographie de l'hématome orientent-ils le diagnostic étiologique d'une hémorragie intraparenchymateuse ?","a":"<ul><li>Une hémorragie intraparenchymateuse (HIP) <strong>profonde</strong> évoque une <strong>HTA</strong>.</li><li>Une HIP <strong>lobaire</strong> chez le <strong>sujet âgé</strong> évoque une <strong>angiopathie amyloïde</strong>.</li><li>Une HIP <strong>lobaire</strong> chez le <strong>sujet jeune</strong> doit faire rechercher une <strong>malformation vasculaire</strong>.</li></ul>"},{"i":"b909f107cea0","n":340,"o":"340-10","u":"Étiologies","t":"Connaître les principales causes d'AVC hémorragiques","q":"Quelles sont les causes d'hémorragie intraparenchymateuse liées à des troubles de l'hémostase ?","a":"<p>Les troubles de l'hémostase sont responsables de plus de 10 % des HIP. Ils peuvent être :</p><ul><li><strong>Acquis</strong> : liés aux <strong>anticoagulants</strong> (responsables d'environ 10 % des HIP) ou à l'alcoolisme.</li><li><strong>Congénitaux</strong> : comme l'hémophilie.</li></ul>"},{"i":"0af543ff32af","n":340,"o":"340-11","u":"Examens complémentaires","t":"Connaître la stratégie d'explorations complémentaires à la phase aigüe d'un AVC","q":"Quelle est l'imagerie cérébrale de première intention à réaliser en urgence devant une suspicion d'AVC, et quelles séquences sont obligatoires ?","a":"<p>L'<strong>IRM cérébrale</strong> est l'examen de première intention.</p><p>Les <strong>quatre séquences obligatoires</strong> sont :</p><ul><li><strong>DWI</strong> (Diffusion).</li><li><strong>FLAIR</strong> (ou T2/FLAIR).</li><li><strong>T2*</strong> (écho de gradient).</li><li><strong>TOF</strong> (Angio-IRM cérébrale).</li></ul>"},{"i":"8d6db0518d5e","n":340,"o":"340-11","u":"Examens complémentaires","t":"Connaître la stratégie d'explorations complémentaires à la phase aigüe d'un AVC","q":"Dans quel contexte la TDM cérébrale sans injection est-elle utilisée dans l'exploration d'un AVC, et que permet-elle d'éliminer spécifiquement à la phase aiguë ?","a":"<p>La <strong>TDM cérébrale sans injection</strong> est utilisée comme <strong>alternative si l'IRM est indisponible</strong>.</p><p>À la phase aiguë, elle permet d'<strong>éliminer immédiatement une hémorragie cérébrale</strong> par la mise en évidence d'une <strong>hyperdensité spontanée</strong>.</p>"},{"i":"bd9e880b8621","n":340,"o":"340-11","u":"Examens complémentaires","t":"Connaître la stratégie d'explorations complémentaires à la phase aigüe d'un AVC","q":"Quel est le rôle de la séquence T2* en IRM dans le protocole de l'AVC et quel est le piège classique associé à la séquence T2 simple ?","a":"<p>La séquence <strong>T2*</strong> est fondamentale car elle recherche la <strong>composante hémorragique</strong> de l'AVC.</p><p>Le piège classique est que la séquence <strong>T2 simple ne fait pas partie du protocole</strong> standard de l'AVC à la phase aiguë.</p>"},{"i":"d4a57104681f","n":340,"o":"340-11","u":"Examens complémentaires","t":"Connaître la stratégie d'explorations complémentaires à la phase aigüe d'un AVC","q":"Quelle est la priorité de la prise en charge d'un AVC à la phase aiguë, et quels sont les gestes systématiques associés à l'imagerie ?","a":"<p>La priorité est de <strong>confirmer l'AVC</strong> et de <strong>différencier ischémie et hémorragie</strong> en urgence, sans retarder une éventuelle revascularisation.</p><p>Les gestes systématiques sont :</p><ul><li>Noter l'<strong>heure de début</strong>.</li><li>Réaliser une <strong>glycémie capillaire</strong>.</li><li>Effectuer un <strong>bilan biologique standard</strong>.</li><li>Réaliser un <strong>ECG</strong>.</li></ul>"},{"i":"0c20153604fb","n":340,"o":"340-15","u":"Prise en charge","t":"Connaître les actions à réaliser lors de la phase pré-hospitalière","q":"Quelle est l'attitude initiale à adopter par les proches ou les témoins face à des symptômes évocateurs d'un AVC en phase pré-hospitalière ?","a":"<p>Il faut <strong>alerter le 15 sans délai</strong> dès l'apparition des symptômes évocateurs d'un AVC (critères FAST).</p>"},{"i":"0edae59f7a42","n":340,"o":"340-15","u":"Prise en charge","t":"Connaître les actions à réaliser lors de la phase pré-hospitalière","q":"Pourquoi est-il crucial de noter l'heure de début des symptômes et les modalités d'installation lors de la suspicion d'un AVC en phase pré-hospitalière ?","a":"<p>Cette information est déterminante car elle conditionne l'<strong>éligibilité du patient aux traitements de revascularisation</strong> (thrombolyse, thrombectomie) dont l'efficacité est corrélée au délai de prise en charge.</p>"},{"i":"abc18bfd1b4d","n":340,"o":"340-15","u":"Prise en charge","t":"Connaître les actions à réaliser lors de la phase pré-hospitalière","q":"Vers quel type d'établissement un patient suspect d'AVC doit-il être orienté en phase pré-hospitalière ?","a":"<p>Le patient doit être acheminé vers un <strong>centre disposant d'une imagerie cérébrale et d'un neurologue</strong> (ou d'une télé-neurologie). Une <strong>information préhospitalière de l'équipe hospitalière</strong> est essentielle.</p>"},{"i":"f13aa55b2b39","n":340,"o":"340-15","u":"Prise en charge","t":"Connaître les actions à réaliser lors de la phase pré-hospitalière","q":"Quelles sont les modalités de transport hospitalier recommandées pour un patient suspect d'AVC en phase pré-hospitalière ?","a":"<p>Le transport doit être <strong>non médicalisé en règle générale</strong>. Un transport médicalisé est réservé aux cas de <strong>trouble de la vigilance</strong> ou de <strong>défaillance cardio-respiratoire</strong>.</p>"},{"i":"faa3ef41c068","n":340,"o":"340-15","u":"Prise en charge","t":"Connaître les actions à réaliser lors de la phase pré-hospitalière","q":"Quelles sont les mesures initiales à prendre en phase pré-hospitalière pour un patient suspect d'AVC, et quelles sont les précautions pharmacologiques à respecter ?","a":"<ul><li>position avec tête à <strong>30°</strong>.</li><li>Maintien de la <strong>normoglycémie</strong> et de la <strong>normothermie</strong>.</li><li><strong>Ne pas administrer d'antihypertenseur</strong>, sauf en cas de chiffres tensionnels extrêmes (>220/120 mmHg pour un infarctus).</li><li><strong>Ne pas administrer d'aspirine</strong> avant la réalisation d'une imagerie cérébrale pour ne pas retarder une thrombolyse et pour ne pas aggraver une éventuelle hémorragie cérébrale.</li></ul>"},{"i":"0159b0572f6e","n":340,"o":"340-16","u":"Prise en charge","t":"Connaître les principes de la prise en charge à la phase aigüe de l'AVC ischémique","q":"Où s'effectue la prise en charge à la phase aiguë de l'infarctus cérébral et quels sont ses objectifs principaux ?","a":"<p>La prise en charge de l'infarctus cérébral à la phase aiguë s'effectue en <strong>unité neurovasculaire</strong>. Elle combine :</p><ul><li>La <strong>revascularisation</strong>.</li><li>Le <strong>traitement antithrombotique</strong>.</li><li>Les <strong>mesures générales</strong>.</li></ul>"},{"i":"24f3db9db226","n":340,"o":"340-16","u":"Prise en charge","t":"Connaître les principes de la prise en charge à la phase aigüe de l'AVC ischémique","q":"Quelles sont les principales mesures générales et pièges à éviter dans la prise en charge de l'infarctus cérébral à la phase aiguë ?","a":"<p>Les mesures générales incluent :</p><ul><li>Le <strong>respect de la poussée tensionnelle</strong> : Traitement uniquement si PA > <strong>220/120 mmHg</strong> (ou > <strong>185/110 mmHg</strong> si revascularisation).</li><li>La lutte contre l'<strong>hyperthermie</strong> et l'<strong>hyperglycémie</strong>.</li><li>La position proclive : <strong>tête à 30°</strong>, pas de lever.</li><li>La recherche systématique de troubles de la <strong>déglutition</strong>.</li><li>La prévention de la <strong>MTEV</strong> : Héparine à doses isocoagulantes (HBPM) en cas d'alitement.</li></ul><p>Pour l'œdème cérébral, on utilise les <strong>macromolécules (mannitol)</strong> et on lutte contre l'hypercapnie et l'hyponatrémie. Une <strong>craniectomie de décompression</strong> est envisagée si infarctus malin.</p><p>Le piège est de ne <strong>jamais administrer de corticoïdes</strong> car ils sont inutiles et délétères sur l'œdème cytotoxique.</p>"},{"i":"a21592f68136","n":340,"o":"340-16","u":"Prise en charge","t":"Connaître les principes de la prise en charge à la phase aigüe de l'AVC ischémique","q":"Quel est le traitement antithrombotique initial de l'infarctus cérébral à la phase aiguë ?","a":"<p>Le traitement antithrombotique initial est l'<strong>aspirine 160-300 mg/jour</strong>. Elle est administrée :</p><ul><li>Dès l'arrivée en l'absence de thrombolyse.</li><li>Après l'imagerie de contrôle à 24h si une thrombolyse a été réalisée.</li></ul><p>Le <strong>clopidogrel</strong> est utilisé en cas de contre-indication à l'aspirine.</p>"},{"i":"fc1a15c41cd1","n":340,"o":"340-16","u":"Prise en charge","t":"Connaître les principes de la prise en charge à la phase aigüe de l'AVC ischémique","q":"Quelles sont les modalités de revascularisation de l'infarctus cérébral à la phase aiguë, et quels sont leurs délais d'indication ?","a":"<p>Les modalités de revascularisation sont :</p><ul><li>La <strong>thrombolyse IV (altéplase, rt-PA)</strong>: Indiquée dans un délai de <strong>moins de 4h30</strong> après l'installation des signes. La décision est prise par un spécialiste neurovasculaire en raison des nombreuses contre-indications et risques (hémorragie cérébrale, angiœdème).</li><li>La <strong>thrombectomie mécanique</strong> (voie endovasculaire) : Indiquée jusqu'à <strong>6h</strong>, extensible jusqu'à <strong>24h</strong> sur <mark style=\"background-color:#E0FFC1\">mismatch imagerie</mark>. Elle ne concerne que les <strong>occlusions proximales</strong> (tronc carotidien, M1/M2 de la cérébrale moyenne, tronc basilaire) et peut être réalisée seule ou en complément de la thrombolyse IV.</li></ul>"},{"i":"3d03acda4886","n":340,"o":"340-2","u":"Epidémiologie","t":"Connaître les facteurs de risque des AVC","q":"Quels sont les trois principaux facteurs de risque modifiables des AVC, et quel est le facteur de risque le plus important ?","a":"<ul><li>Les trois principaux facteurs de risque modifiables sont l'<strong>HTA</strong>, le <strong>tabac</strong> et le <strong>diabète</strong>.</li><li>L'<strong>HTA</strong> est le principal facteur de risque, multipliant le risque par <strong>4</strong> (RR=4), et est impliquée dans plus de 50% des AVC, qu'ils soient ischémiques ou hémorragiques.</li></ul>"},{"i":"604f8739f0bd","n":340,"o":"340-2","u":"Epidémiologie","t":"Connaître les facteurs de risque des AVC","q":"Citez cinq autres facteurs de risque modifiables d'AVC, en dehors de l'HTA, du tabac, du diabète et de la dyslipidémie.","a":"<ul><li>L'<strong>alcoolisme chronique</strong> (au-delà de 3 verres/jour).</li><li>La <strong>fibrillation atriale</strong> (cardiopathie emboligène majeure).</li><li>La <strong>migraine avec aura</strong> (surtout chez la femme jeune avec tabac et contraception orale).</li><li>La <strong>contraception œstroprogestative</strong> (faible sur-risque, synergique avec le tabac).</li><li>La <strong>sédentarité</strong> et l'<strong>alimentation déséquilibrée</strong> (également des facteurs de risque modifiables principaux mentionnés initialement).</li></ul>"},{"i":"a7fe00d8466e","n":340,"o":"340-2","u":"Epidémiologie","t":"Connaître les facteurs de risque des AVC","q":"Quelle est la tranche d'âge la plus fréquemment touchée par les AVC selon l'épidémiologie française ?","a":"<p>L'AVC touche majoritairement les sujets de <strong>65 ans et plus</strong> (75 % des cas), avec un âge moyen de survenue de <strong>73 ans</strong>.</p>"},{"i":"b1572576e37d","n":340,"o":"340-2","u":"Epidémiologie","t":"Connaître les facteurs de risque des AVC","q":"Quels sont les facteurs de risque non modifiables des AVC ?","a":"<ul><li>L'<strong>âge</strong>.</li><li>Le <strong>sexe masculin</strong>.</li><li>Les <strong>antécédents familiaux</strong> et <strong>personnels</strong> d'événement cérébro-vasculaire.</li></ul>"},{"i":"ea6926afba21","n":340,"o":"340-2","u":"Epidémiologie","t":"Connaître les facteurs de risque des AVC","q":"Quel est le piège à éviter concernant la prévention primaire neurovasculaire par aspirine et la chirurgie d'une sténose carotidienne asymptomatique ?","a":"<ul><li>Il n'y a <strong>aucun intérêt à l'aspirine au long cours</strong> en prévention primaire neurovasculaire chez un patient sans antécédent d'AIT ou d'infarctus avéré.</li><li>La chirurgie d'une sténose carotide asymptomatique n'est discutée que si elle est <strong>supérieure à 60%</strong> et que le patient présente une espérance de vie <strong>supérieure à 5 ans</strong>.</li></ul>"},{"i":"13ae063169db","n":340,"o":"340-3","u":"Identifier une urgence","t":"Connaître l'urgence diagnostique et thérapeutique des AVC","q":"Quelle est la conduite à tenir immédiate pour toute suspicion d'AVC ?","a":"<p>Devant toute suspicion d'AVC, il faut :</p><ul><li><strong>Alerter le 15</strong> sans délai.</li><li><strong>Noter l'heure de début des symptômes</strong>, car elle conditionne l'éligibilité aux traitements de revascularisation.</li><li><strong>Orienter le patient</strong> vers une Unité NeuroVasculaire (UNV), quels que soient l'âge, le sexe ou la gravité des symptômes.</li></ul>"},{"i":"1c0f3b78d0d3","n":340,"o":"340-3","u":"Identifier une urgence","t":"Connaître l'urgence diagnostique et thérapeutique des AVC","q":"Pourquoi une imagerie cérébrale est-elle systématiquement nécessaire en urgence devant toute suspicion d'AVC ?","a":"<p>L'imagerie cérébrale en urgence est indispensable car elle est la seule à permettre de <strong>distinguer un AVC ischémique d'un AVC hémorragique</strong>. Cette distinction est fondamentale avant d'initier tout traitement, notamment la revascularisation, qui n'est indiquée que pour les AVC ischémiques.</p>"},{"i":"3341eb23d50b","n":340,"o":"340-3","u":"Identifier une urgence","t":"Connaître l'urgence diagnostique et thérapeutique des AVC","q":"Pourquoi l'Accident Vasculaire Cérébral (AVC) est-il une urgence diagnostique et thérapeutique absolue ?","a":"<p>L'AVC est une urgence absolue car le <strong>pronostic vital immédiat</strong> et le <strong>pronostic fonctionnel</strong> ultérieur dépendent de la rapidité de la prise en charge. Chaque minute d'ischémie détruit <strong>2 millions de neurones</strong>, d'où l'adage « time is brain ».</p>"},{"i":"914cca1705a7","n":340,"o":"340-3","u":"Identifier une urgence","t":"Connaître l'urgence diagnostique et thérapeutique des AVC","q":"Quels sont les critères cliniques simples pour reconnaître un AVC, diffusés au grand public ?","a":"<p>Les critères de reconnaissance rapide de l'AVC sont regroupés sous l'acronyme <strong>FAST</strong> :</p><ul><li><strong>F</strong>ace : asymétrie faciale</li><li><strong>A</strong>rm : déficit moteur d'un membre (généralement supérieur)</li><li><strong>S</strong>peech : trouble du langage (aphasie ou dysarthrie)</li><li><strong>T</strong>ime : noter l'heure de début des symptômes et appeler le 15 sans délai</li></ul>"},{"i":"9d0c6ec89df8","n":340,"o":"340-3","u":"Identifier une urgence","t":"Connaître l'urgence diagnostique et thérapeutique des AVC","q":"Quelles sont les fenêtres thérapeutiques pour la revascularisation en cas d'AVC ischémique ?","a":"<p>Les fenêtres thérapeutiques sont étroites :</p><ul><li>La <strong>thrombolyse intraveineuse</strong> est possible jusqu'à <strong>4 heures 30 minutes</strong> après le début des symptômes.</li><li>La <strong>thrombectomie mécanique</strong> est réalisable jusqu'à <strong>6 heures</strong>, et peut être étendue à <strong>24 heures</strong> sur sélection par imagerie avancée.</li></ul>"},{"i":"b95b5a26bd11","n":340,"o":"340-5","u":"Diagnostic positif","t":"Connaître les arguments cliniques diagnostiques en faveur des infarctus cérébraux constitués, accident ischémique transitoire, hémorragies intraparenchymateuses","q":"Quels sont les signes cliniques caractéristiques d'un infarctus cérébral constitué dans le territoire de l'artère sylvienne superficielle (hémisphère majeur gauche) ?","a":"<p>Un infarctus dans le territoire de l'artère sylvienne superficielle de l'hémisphère majeur (gauche) se caractérise par :</p><ul><li>Un <strong>déficit sensitivomoteur brachiofacial</strong>.</li><li>Une <strong>paralysie faciale centrale</strong>.</li><li>Une <strong>hémianopsie latérale homonyme (HLH)</strong>.</li><li>Une <strong>aphasie de Broca</strong> (si atteinte antérieure) ou de <strong>Wernicke</strong> (si atteinte postérieure).</li><li>Un <strong>syndrome de Gerstmann</strong>.</li></ul>"},{"i":"ca28daf494a6","n":340,"o":"340-5","u":"Diagnostic positif","t":"Connaître les arguments cliniques diagnostiques en faveur des infarctus cérébraux constitués, accident ischémique transitoire, hémorragies intraparenchymateuses","q":"Quels sont les signes cliniques évocateurs d'un accident ischémique transitoire (AIT) carotidien ?","a":"<p>Les signes cliniques évocateurs d'un AIT carotidien sont :</p><ul><li>Une <strong>cécité monoculaire</strong> (appelée <strong>amaurose fugace</strong>).</li><li>Une <strong>aphasie</strong>.</li><li>Des <strong>troubles moteurs et/ou sensitifs unilatéraux</strong> touchant la face et/ou les membres.</li></ul>"},{"i":"e22d45169323","n":340,"o":"340-5","u":"Diagnostic positif","t":"Connaître les arguments cliniques diagnostiques en faveur des infarctus cérébraux constitués, accident ischémique transitoire, hémorragies intraparenchymateuses","q":"Quels sont les signes cliniques orientant vers un infarctus cérébral constitué dans le territoire de l'artère cérébrale antérieure ?","a":"<p>Un infarctus dans le territoire de l'artère cérébrale antérieure se manifeste par :</p><ul><li>Une <strong>hémiplégie à prédominance crurale</strong>.</li><li>Des troubles sensitifs.</li><li>Une <strong>apraxie idéomotrice de la main</strong>.</li><li>Un syndrome frontal.</li><li>Un <strong>mutisme akinétique</strong> si l'atteinte est bilatérale.</li></ul>"},{"i":"e950c86dcb7d","n":340,"o":"340-5","u":"Diagnostic positif","t":"Connaître les arguments cliniques diagnostiques en faveur des infarctus cérébraux constitués, accident ischémique transitoire, hémorragies intraparenchymateuses","q":"Comment se manifeste cliniquement une occlusion carotidienne complète, dite « T carotidien » ?","a":"<p>L'occlusion carotidienne se manifeste par :</p><ul><li>Des <strong>infarctus jonctionnels</strong> associant un infarctus cérébral antérieur et sylvien.</li><li>Un <strong>syndrome optico-pyramidal</strong>, combinant une <strong>cécité monoculaire homolatérale</strong> à l'occlusion et une <strong>hémiplégie controlatérale</strong>.</li></ul>"},{"i":"ff6783442e7f","n":340,"o":"340-5","u":"Diagnostic positif","t":"Connaître les arguments cliniques diagnostiques en faveur des infarctus cérébraux constitués, accident ischémique transitoire, hémorragies intraparenchymateuses","q":"Quelles sont les particularités cliniques d'une hémorragie intraparenchymateuse (HIP) par rapport à un infarctus cérébral ?","a":"<p>Les particularités cliniques de l'HIP sont :</p><ul><li>Un déficit neurologique <strong>non systématisé à un territoire artériel</strong>, dépendant de la localisation de l'hématome.</li><li>Une aggravation des symptômes <strong>en tache d'huile</strong>.</li><li>Des <strong>céphalées plus fréquentes et plus sévères</strong>.</li><li>Des <strong>troubles de la vigilance plus précoces</strong>, en raison de l'hypertension intracrânienne associée.</li></ul><p>Il est important de noter qu'aucun argument clinique ne permet de différencier de façon fiable un infarctus d'une hémorragie, l'imagerie cérébrale est indispensable.</p>"},{"i":"622b4f849310","n":340,"o":"340-8","u":"Diagnostic positif","t":"Connaître les signes de gravité d'un AVC","q":"Quelles sont les spécificités des hématomes intracérébraux (HIC) comme signes de gravité d'un AVC ?","a":"<ul><li>Un <strong>hématome volumineux</strong>.</li><li>Un <strong>effet de masse</strong>, avec un risque d'<strong>engagement temporal</strong>.</li><li>Une <strong>inondation ventriculaire</strong> et une <strong>hydrocéphalie aiguë</strong>.</li></ul>"},{"i":"a508db354060","n":340,"o":"340-8","u":"Diagnostic positif","t":"Connaître les signes de gravité d'un AVC","q":"Quelle sévérité du déficit moteur et quelle topographie lésionnelle orientent vers un AVC grave ?","a":"<ul><li>Une <strong>sévérité du déficit</strong> avec un déficit massif, un score <strong>NIHSS élevé</strong>, ou une <strong>atteinte motrice bilatérale</strong>.</li><li>Une <strong>topographie</strong> avec une <strong>occlusion du tronc basilaire</strong> (entraînant coma, <strong>locked-in syndrome</strong>) ou une <strong>occlusion artérielle proximale</strong>.</li></ul>"},{"i":"d1ea347176ff","n":340,"o":"340-8","u":"Diagnostic positif","t":"Connaître les signes de gravité d'un AVC","q":"Quels sont les signes de gravité liés à l'état de conscience en cas d'AVC ?","a":"<p>Les signes de gravité liés à l'état de conscience d'un AVC sont les <strong>troubles de la vigilance</strong> ou le <strong>coma</strong>, qui peuvent être secondaires à une lésion directe du tronc cérébral ou à un effet de masse.</p>"},{"i":"d633f190436b","n":340,"o":"340-8","u":"Diagnostic positif","t":"Connaître les signes de gravité d'un AVC","q":"Quelles sont les complications immédiates de l'AVC qui sont des signes de gravité ?","a":"<ul><li>La <strong>transformation hémorragique</strong>.</li><li>La <strong>pneumopathie d'inhalation</strong> suite à des troubles de la déglutition (notamment dans le syndrome de Wallenberg).</li><li>Un <strong>état de mal épileptique</strong>.</li></ul>"},{"i":"f401cf18a3bf","n":340,"o":"340-8","u":"Diagnostic positif","t":"Connaître les signes de gravité d'un AVC","q":"Qu'est-ce qu'un infarctus cérébral malin dans le cadre d'un AVC, et quels en sont les signes de gravité ?","a":"<p>Un infarctus cérébral malin est souvent un <strong>infarctus sylvien total</strong> chez le sujet jeune. Il se caractérise par un <strong>œdème cytotoxique</strong> et une <strong>HTIC</strong> (hypertension intracrânienne) qui surviennent entre <strong>24 et 72 heures</strong>, avec un risque d'<strong>engagement cérébral</strong>.</p>"},{"i":"21ff5c0daaff","n":340,"o":"340-9","u":"Étiologies","t":"Connaître les principales causes d'AVC ischémiques","q":"Dans le contexte des AVC ischémiques, quelles sont les caractéristiques clés de l'athérosclérose comme étiologie ?","a":"<p>L'athérosclérose est caractérisée par une <strong>sténose &gt; 50 %</strong> en amont de l'infarctus, associée à des <strong>facteurs de risque vasculaire</strong>. Le mécanisme peut être <strong>thromboembolique, thrombotique</strong> ou <strong>hémodynamique</strong>.</p>"},{"i":"2d6add05a748","n":340,"o":"340-9","u":"Étiologies","t":"Connaître les principales causes d'AVC ischémiques","q":"Comment les lacunes se forment-elles en tant qu'étiologie d'AVC ischémique et quel en est le principal facteur de risque ?","a":"<p>Les lacunes résultent de l'<strong>occlusion d'une artériole profonde</strong> par <strong>lipohyalinose</strong>. Le principal facteur de risque associé est l'<strong>hypertension artérielle (HTA)</strong>.</p>"},{"i":"7cc0830ed802","n":340,"o":"340-9","u":"Étiologies","t":"Connaître les principales causes d'AVC ischémiques","q":"Citez quelques exemples de causes rares d'AVC ischémiques.","a":"<p>Les causes rares d'AVC ischémiques incluent :</p><ul><li>Les <strong>états prothrombotiques</strong> (maladie de Vaquez, SAPL, CIVD).</li><li>Les <strong>artérites</strong> (comme l'artérite de Horton).</li><li>Les <strong>maladies métaboliques</strong> (drépanocytose, maladie de Fabry, mitochondriopathies).</li></ul>"},{"i":"c0637b271642","n":340,"o":"340-9","u":"Étiologies","t":"Connaître les principales causes d'AVC ischémiques","q":"Quelle est la principale cardiopathie emboligène responsable d'AVC ischémique et quand doit-on la suspecter ?","a":"<p>La <strong>fibrillation atriale</strong> est de loin la première cause de cardiopathie emboligène (<strong>50 %</strong> des cas). On doit suspecter une origine cardio-embolique devant des <strong>infarctus simultanés ou distincts dans des territoires artériels différents</strong> (par exemple, infarctus cortico-sous-corticaux bilatéraux).</p>"},{"i":"d510d3c8262b","n":340,"o":"340-9","u":"Étiologies","t":"Connaître les principales causes d'AVC ischémiques","q":"Quelle est une cause majeure d'AVC ischémique chez le sujet jeune parmi les causes rares ?","a":"<p>La <strong>dissection cervico-encéphalique</strong> est une cause majeure d'infarctus cérébral chez le sujet jeune.</p>"},{"i":"e601a86ecf00","n":340,"o":"340-9","u":"Étiologies","t":"Connaître les principales causes d'AVC ischémiques","q":"Quelles sont les quatre principales catégories étiologiques des AVC ischémiques, selon leur fréquence relative ?","a":"<p>Les quatre principales catégories étiologiques des AVC ischémiques sont :</p><ul><li>L'<strong>athérosclérose (macroangiopathie)</strong> : environ 30 % des cas.</li><li>Les <strong>cardiopathies emboligènes</strong> : environ 20 % des cas.</li><li>Les <strong>lacunes (microangiopathie)</strong> : environ 20 % des cas.</li><li>Les <strong>causes rares et indéterminées</strong> : représentent le reste, dont 25 % de causes indéterminées.</li></ul>"}]};